/**
 * useExport Hook Tests
 *
 * Tests for the useExport hook including:
 * - Export modal state management
 * - Export job creation
 * - Progress tracking
 * - Error handling
 * - Hashtag suggestion generation
 */

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { renderHook, waitFor, act } from "@testing-library/react";
import { useExport } from "@/hooks/useExport";
import * as exportApi from "@/lib/api/export";
import type { ExportContent, ExportRequest } from "@/components/export/types";

// Mock the export API module
vi.mock("@/lib/api/export", () => ({
  startExport: vi.fn(),
  getExportStatus: vi.fn(),
  getExportDownloadUrl: vi.fn(),
  getStatusMessage: vi.fn((status: string) => {
    const messages: Record<string, string> = {
      pending: "Export queued...",
      preparing: "Preparing content...",
      processing: "Processing video...",
      encoding: "Encoding for platforms...",
      completed: "Export complete!",
      failed: "Export failed",
    };
    return messages[status] || "Unknown status";
  }),
  isExportFinished: vi.fn((status: string) => status === "completed" || status === "failed"),
  isExportSuccessful: vi.fn((status: string) => status === "completed"),
}));

describe("useExport Hook", () => {
  const mockContent: ExportContent = {
    id: "content-123",
    type: "clip",
    title: "Test Clip",
    thumbnailUrl: "https://example.com/thumb.jpg",
    duration: 30,
    createdAt: new Date(),
  };

  const mockExportRequest: ExportRequest = {
    contentId: "content-123",
    platforms: ["youtube", "tiktok"],
    caption: "Test caption",
    hashtags: ["test", "viral"],
    formatOptions: {
      format: "mp4",
      quality: "1080p",
      aspectRatio: "9:16",
    },
    customFilename: "my-export",
  };

  beforeEach(() => {
    vi.clearAllMocks();
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  describe("Modal State", () => {
    it("should initialize with modal closed", () => {
      const { result } = renderHook(() => useExport());

      expect(result.current.isModalOpen).toBe(false);
      expect(result.current.currentContent).toBeNull();
    });

    it("should open modal with content", () => {
      const { result } = renderHook(() => useExport());

      act(() => {
        result.current.openExport(mockContent);
      });

      expect(result.current.isModalOpen).toBe(true);
      expect(result.current.currentContent).toEqual(mockContent);
    });

    it("should close modal", () => {
      vi.useFakeTimers();
      const { result } = renderHook(() => useExport());

      act(() => {
        result.current.openExport(mockContent);
      });

      expect(result.current.isModalOpen).toBe(true);

      act(() => {
        result.current.closeExport();
      });

      expect(result.current.isModalOpen).toBe(false);

      // Content resets after 300ms animation delay
      act(() => {
        vi.advanceTimersByTime(350);
      });

      expect(result.current.currentContent).toBeNull();
      expect(result.current.progress.status).toBe("idle");
    });
  });

  describe("Progress State", () => {
    it("should initialize with idle progress", () => {
      const { result } = renderHook(() => useExport());

      expect(result.current.progress).toEqual({
        status: "idle",
        progress: 0,
      });
    });
  });

  describe("handleExport - Success Flow", () => {
    it("should start export and complete successfully", async () => {
      vi.useFakeTimers();

      const mockStartResponse = {
        exportId: "export-456",
        status: "pending" as const,
        createdAt: new Date().toISOString(),
      };

      const mockStatusCompleted = {
        exportId: "export-456",
        status: "completed" as const,
        progress: 100,
        message: "Export complete!",
        downloadUrl: "https://example.com/download/export-456",
        filename: "my-export.mp4",
        fileSize: 1024000,
      };

      vi.mocked(exportApi.startExport).mockResolvedValue(mockStartResponse);
      vi.mocked(exportApi.getExportStatus).mockResolvedValue(mockStatusCompleted);

      const onSuccess = vi.fn();
      const { result } = renderHook(() => useExport({ onSuccess }));

      let exportPromise: Promise<any>;

      await act(async () => {
        exportPromise = result.current.handleExport(mockExportRequest);
        // Advance to allow startExport to resolve
        await vi.advanceTimersByTimeAsync(100);
      });

      expect(exportApi.startExport).toHaveBeenCalledWith("content-123", {
        platforms: ["youtube", "tiktok"],
        caption: "Test caption",
        hashtags: ["test", "viral"],
        formatOptions: {
          format: "mp4",
          quality: "1080p",
          aspectRatio: "9:16",
        },
        customFilename: "my-export",
      });

      // Advance through poll interval
      await act(async () => {
        await vi.advanceTimersByTimeAsync(2500);
      });

      const exportResult = await exportPromise!;

      expect(exportResult.id).toBe("export-456");
      expect(exportResult.downloadUrl).toBe("https://example.com/download/export-456");
      expect(result.current.progress.status).toBe("completed");
      expect(onSuccess).toHaveBeenCalled();
    });
  });

  describe("handleExport - Error Flow", () => {
    it("should handle export start error", async () => {
      vi.mocked(exportApi.startExport).mockRejectedValue(
        new Error("Failed to start export")
      );

      const onError = vi.fn();
      const { result } = renderHook(() => useExport({ onError }));

      let error: Error | undefined;
      await act(async () => {
        try {
          await result.current.handleExport(mockExportRequest);
        } catch (e) {
          error = e as Error;
        }
      });

      expect(error!.message).toBe("Failed to start export");

      // Wait for error state to be updated
      await waitFor(() => {
        expect(result.current.progress.status).toBe("error");
      });

      expect(result.current.progress.error).toBe("Failed to start export");
      expect(onError).toHaveBeenCalled();
    });

    it("should handle export failure status", async () => {
      vi.useFakeTimers();

      const mockStartResponse = {
        exportId: "export-789",
        status: "pending" as const,
        createdAt: new Date().toISOString(),
      };

      const mockStatusFailed = {
        exportId: "export-789",
        status: "failed" as const,
        progress: 0,
        error: "Encoding failed",
      };

      vi.mocked(exportApi.startExport).mockResolvedValue(mockStartResponse);
      vi.mocked(exportApi.getExportStatus).mockResolvedValue(mockStatusFailed);

      const onError = vi.fn();
      const { result } = renderHook(() => useExport({ onError }));

      let exportError: Error | undefined;
      let exportPromise: Promise<any>;

      await act(async () => {
        // Start export and immediately attach catch handler to prevent unhandled rejection
        exportPromise = result.current.handleExport(mockExportRequest);
        exportPromise.catch((e) => {
          exportError = e as Error;
        });
        // Advance to allow startExport to resolve
        await vi.advanceTimersByTimeAsync(100);
      });

      // Advance through poll to trigger the failure and wait for promise to settle
      await act(async () => {
        await vi.advanceTimersByTimeAsync(2500);
        // Allow the promise rejection to be handled
        await vi.runAllTimersAsync();
      });

      expect(exportError!.message).toBe("Encoding failed");
      expect(result.current.progress.status).toBe("error");
      expect(onError).toHaveBeenCalled();
    });
  });

  describe("stopPolling", () => {
    it("should stop active polling when called", async () => {
      vi.useFakeTimers();

      const mockStartResponse = {
        exportId: "export-stop",
        status: "pending" as const,
        createdAt: new Date().toISOString(),
      };

      const mockStatusProcessing = {
        exportId: "export-stop",
        status: "processing" as const,
        progress: 30,
      };

      vi.mocked(exportApi.startExport).mockResolvedValue(mockStartResponse);
      vi.mocked(exportApi.getExportStatus).mockResolvedValue(mockStatusProcessing);

      const { result } = renderHook(() => useExport());

      await act(async () => {
        result.current.handleExport(mockExportRequest);
        await vi.advanceTimersByTimeAsync(100);
      });

      // First poll
      await act(async () => {
        await vi.advanceTimersByTimeAsync(2500);
      });

      const callCount = vi.mocked(exportApi.getExportStatus).mock.calls.length;

      act(() => {
        result.current.stopPolling();
      });

      // Advance time - polling should not continue
      await act(async () => {
        await vi.advanceTimersByTimeAsync(10000);
      });

      // Call count should not have increased significantly
      expect(vi.mocked(exportApi.getExportStatus).mock.calls.length).toBeLessThanOrEqual(
        callCount + 1
      );
    });
  });

  describe("generateHashtagSuggestions", () => {
    it("should generate hashtag suggestions for clip content", () => {
      const { result } = renderHook(() => useExport());

      const clipContent: ExportContent = {
        id: "clip-1",
        type: "clip",
        title: "Test Clip",
        createdAt: new Date(),
      };

      const suggestions = result.current.generateHashtagSuggestions(clipContent);

      expect(suggestions.length).toBeGreaterThan(0);
      expect(suggestions.some((s) => s.tag === "viral")).toBe(true);
      expect(suggestions.some((s) => s.tag === "contentcreator")).toBe(true);
      expect(suggestions.some((s) => s.platforms.includes("tiktok"))).toBe(true);
    });

    it("should generate hashtag suggestions for post content", () => {
      const { result } = renderHook(() => useExport());

      const postContent: ExportContent = {
        id: "post-1",
        type: "post",
        title: "Test Post",
        createdAt: new Date(),
      };

      const suggestions = result.current.generateHashtagSuggestions(postContent);

      expect(suggestions.length).toBeGreaterThan(0);
      expect(suggestions.some((s) => s.tag === "socialmedia")).toBe(true);
      expect(suggestions.some((s) => s.platforms.includes("linkedin"))).toBe(true);
    });

    it("should include generic suggestions for all content types", () => {
      const { result } = renderHook(() => useExport());

      const content: ExportContent = {
        id: "any-1",
        type: "clip",
        title: "Any Content",
        createdAt: new Date(),
      };

      const suggestions = result.current.generateHashtagSuggestions(content);

      expect(suggestions.some((s) => s.tag === "fyp")).toBe(true);
      expect(suggestions.some((s) => s.tag === "explore")).toBe(true);
      expect(suggestions.some((s) => s.tag === "foryou")).toBe(true);
    });
  });

  describe("Export History", () => {
    it("should add completed exports to history", async () => {
      vi.useFakeTimers();

      const mockStartResponse = {
        exportId: "history-export-1",
        status: "pending" as const,
        createdAt: new Date().toISOString(),
      };

      const mockStatusCompleted = {
        exportId: "history-export-1",
        status: "completed" as const,
        progress: 100,
        downloadUrl: "https://example.com/download",
        filename: "export.mp4",
        fileSize: 1024000,
      };

      vi.mocked(exportApi.startExport).mockResolvedValue(mockStartResponse);
      vi.mocked(exportApi.getExportStatus).mockResolvedValue(mockStatusCompleted);

      const { result } = renderHook(() => useExport());

      expect(result.current.exportHistory).toHaveLength(0);

      let exportPromise: Promise<any>;

      await act(async () => {
        exportPromise = result.current.handleExport(mockExportRequest);
        // Advance to allow startExport to resolve
        await vi.advanceTimersByTimeAsync(100);
      });

      // Advance through poll interval and wait for promise to resolve
      await act(async () => {
        await vi.advanceTimersByTimeAsync(2500);
        await exportPromise!;
      });

      expect(result.current.exportHistory).toHaveLength(1);
      expect(result.current.exportHistory[0].id).toBe("history-export-1");
      expect(result.current.exportHistory[0].platforms).toEqual(["youtube", "tiktok"]);
    });
  });

  describe("Cleanup", () => {
    it("should cleanup polling on unmount", async () => {
      vi.useFakeTimers();

      const mockStartResponse = {
        exportId: "cleanup-export",
        status: "pending" as const,
        createdAt: new Date().toISOString(),
      };

      const mockStatusProcessing = {
        exportId: "cleanup-export",
        status: "processing" as const,
        progress: 50,
      };

      vi.mocked(exportApi.startExport).mockResolvedValue(mockStartResponse);
      vi.mocked(exportApi.getExportStatus).mockResolvedValue(mockStatusProcessing);

      const { result, unmount } = renderHook(() => useExport());

      await act(async () => {
        result.current.handleExport(mockExportRequest);
        await vi.advanceTimersByTimeAsync(100);
      });

      await act(async () => {
        await vi.advanceTimersByTimeAsync(2500);
      });

      const callCount = vi.mocked(exportApi.getExportStatus).mock.calls.length;

      unmount();

      // Advance time after unmount
      await act(async () => {
        await vi.advanceTimersByTimeAsync(10000);
      });

      // No additional calls should have been made after unmount
      expect(vi.mocked(exportApi.getExportStatus).mock.calls.length).toBeLessThanOrEqual(
        callCount + 1
      );
    });
  });

  describe("Batch Export", () => {
    it("should export multiple items and collect results", async () => {
      vi.useFakeTimers();

      const contents: ExportContent[] = [
        { id: "content-1", type: "clip", title: "Clip 1", createdAt: new Date() },
        { id: "content-2", type: "clip", title: "Clip 2", createdAt: new Date() },
      ];

      const baseRequest: Omit<ExportRequest, "contentId"> = {
        platforms: ["youtube"],
        caption: "",
        hashtags: [],
        formatOptions: { format: "mp4", quality: "1080p", aspectRatio: "16:9" },
      };

      let exportIdCounter = 0;
      vi.mocked(exportApi.startExport).mockImplementation(async () => ({
        exportId: `batch-export-${++exportIdCounter}`,
        status: "pending" as const,
        createdAt: new Date().toISOString(),
      }));

      vi.mocked(exportApi.getExportStatus).mockImplementation(async (exportId) => ({
        exportId,
        status: "completed" as const,
        progress: 100,
        downloadUrl: `https://example.com/download/${exportId}`,
        filename: `${exportId}.mp4`,
        fileSize: 1024000,
      }));

      const { result } = renderHook(() => useExport());

      let batchPromise: Promise<any>;

      await act(async () => {
        batchPromise = result.current.batchExport(contents, baseRequest);
        // Process first export
        await vi.advanceTimersByTimeAsync(3000);
      });

      await act(async () => {
        // Process second export
        await vi.advanceTimersByTimeAsync(3000);
      });

      const batchResult = await batchPromise!;

      expect(batchResult.results).toHaveLength(2);
      expect(batchResult.errors).toHaveLength(0);
      expect(exportApi.startExport).toHaveBeenCalledTimes(2);
    });
  });
});

/**
 * useSessions Hook Tests
 *
 * Tests for the useSessions and useSession hooks including:
 * - Initial data loading
 * - Session CRUD operations
 * - Error handling
 * - WebSocket integration
 * - Authentication context integration
 */

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { renderHook, waitFor, act } from "@testing-library/react";
import type { ReactNode } from "react";
import React from "react";
import { createMockApiSession } from "../setup";

// Mock environment variables first
vi.stubEnv("NEXT_PUBLIC_WS_URL", "ws://localhost:3124");
vi.stubEnv("NEXT_PUBLIC_API_URL", "http://localhost:3123");

// Mock the API module
vi.mock("@/lib/api/sessions", () => ({
  getSessions: vi.fn(),
  getSessionById: vi.fn(),
  startSession: vi.fn(),
  endSession: vi.fn(),
  updateSession: vi.fn(),
  deleteSession: vi.fn(),
  getSessionOutputs: vi.fn(),
}));

// Import the mocked module
import * as sessionsApi from "@/lib/api/sessions";

// Mock values
const mockAccessToken = "test-access-token";

// Mock the auth context
vi.mock("@/lib/contexts/AuthContext", () => ({
  useAuth: vi.fn(() => ({
    accessToken: mockAccessToken,
    isAuthenticated: true,
    user: null,
    login: vi.fn(),
    register: vi.fn(),
    logout: vi.fn(),
    refreshSession: vi.fn(),
    clearError: vi.fn(),
    refreshToken: null,
    isLoading: false,
    error: null,
  })),
}));

import { useAuth } from "@/lib/contexts/AuthContext";

// Mock the WebSocket context
const mockConnect = vi.fn();
const mockDisconnect = vi.fn();
const mockClearEvents = vi.fn();

vi.mock("@/contexts/WebSocketContext", () => ({
  useWebSocket: vi.fn(() => ({
    connect: mockConnect,
    disconnect: mockDisconnect,
    isConnected: true,
    events: [],
    outputs: [],
    clips: [],
    moments: [],
    transcripts: [],
    clearEvents: mockClearEvents,
    connectionState: "connected",
  })),
}));

import { useWebSocket } from "@/contexts/WebSocketContext";

// Import hooks after mocks
import { useSessions, useSession } from "@/hooks/useSessions";

describe("useSessions Hook", () => {
  const mockApiSessions = [
    createMockApiSession({ id: "session-1", title: "Session 1" }),
    createMockApiSession({ id: "session-2", title: "Session 2", isActive: false, endedAt: new Date().toISOString() }),
  ];

  const mockPagination = { limit: 50, offset: 0, total: 2 };

  beforeEach(() => {
    vi.clearAllMocks();

    // Reset auth mock
    vi.mocked(useAuth).mockReturnValue({
      accessToken: mockAccessToken,
      isAuthenticated: true,
      user: null,
      login: vi.fn(),
      register: vi.fn(),
      logout: vi.fn(),
      refreshSession: vi.fn(),
      clearError: vi.fn(),
      refreshToken: null,
      isLoading: false,
      error: null,
    });

    // Reset WebSocket mock
    vi.mocked(useWebSocket).mockReturnValue({
      connect: mockConnect,
      disconnect: mockDisconnect,
      isConnected: true,
      events: [],
      outputs: [],
      clips: [],
      moments: [],
      transcripts: [],
      clearEvents: mockClearEvents,
      connectionState: "connected",
    });

    // Default mock for getSessions
    vi.mocked(sessionsApi.getSessions).mockResolvedValue({
      sessions: mockApiSessions,
      pagination: mockPagination,
    });
  });

  afterEach(() => {
    vi.clearAllTimers();
    vi.useRealTimers();
  });

  describe("Initial Load", () => {
    it("should load sessions on mount", async () => {
      const { result } = renderHook(() => useSessions(undefined, false));

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(result.current.sessions).toHaveLength(2);
      expect(result.current.error).toBeNull();
      expect(sessionsApi.getSessions).toHaveBeenCalledWith(50, 0, mockAccessToken, {});
    });

    it("should identify active session from loaded sessions", async () => {
      const sessionsWithActive = [
        createMockApiSession({ id: "session-1", title: "Active Session", isActive: true }),
        createMockApiSession({ id: "session-2", title: "Ended Session", isActive: false, endedAt: new Date().toISOString() }),
      ];

      vi.mocked(sessionsApi.getSessions).mockResolvedValue({
        sessions: sessionsWithActive,
        pagination: mockPagination,
      });

      const { result } = renderHook(() => useSessions(undefined, false));

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(result.current.activeSession).not.toBeNull();
      expect(result.current.activeSession?.id).toBe("session-1");
      expect(result.current.activeSession?.status).toBe("live");
    });

    it("should handle empty sessions list", async () => {
      vi.mocked(sessionsApi.getSessions).mockResolvedValue({
        sessions: [],
        pagination: { limit: 50, offset: 0, total: 0 },
      });

      const { result } = renderHook(() => useSessions(undefined, false));

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(result.current.sessions).toHaveLength(0);
      expect(result.current.activeSession).toBeNull();
      expect(result.current.error).toBeNull();
    });

    it("should handle API error on initial load", async () => {
      vi.mocked(sessionsApi.getSessions).mockRejectedValue(
        new Error("Network error")
      );

      const { result } = renderHook(() => useSessions(undefined, false));

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(result.current.error).toBe("Network error");
    });
  });

  describe("WebSocket Integration", () => {
    it("should connect to WebSocket on mount when autoConnect is true", async () => {
      const { result } = renderHook(() => useSessions(undefined, true));

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(mockConnect).toHaveBeenCalled();
    });

    it("should not connect to WebSocket when autoConnect is false", async () => {
      const { result } = renderHook(() => useSessions(undefined, false));

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(mockConnect).not.toHaveBeenCalled();
    });

    it("should disconnect and clear events on unmount", async () => {
      const { result, unmount } = renderHook(() => useSessions(undefined, true));

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      unmount();

      expect(mockDisconnect).toHaveBeenCalled();
      expect(mockClearEvents).toHaveBeenCalled();
    });
  });

  describe("Authentication", () => {
    it("should expose isAuthenticated from auth context", async () => {
      const { result } = renderHook(() => useSessions(undefined, false));

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(result.current.isAuthenticated).toBe(true);
    });

    it("should pass access token to API calls", async () => {
      const { result } = renderHook(() => useSessions(undefined, false));

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(sessionsApi.getSessions).toHaveBeenCalledWith(50, 0, mockAccessToken, {});
    });
  });

  describe("createSession", () => {
    it("should create a new session and refresh list", async () => {
      const newSessionResponse = { sessionId: "new-session-id", startedAt: Date.now() };

      vi.mocked(sessionsApi.startSession).mockResolvedValue(newSessionResponse);

      const { result } = renderHook(() => useSessions(undefined, false));

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      const config = {
        workflow: "streamer" as const,
        captureMode: "av" as const,
        title: "New Session",
      };

      let response;
      await act(async () => {
        response = await result.current.createSession(config);
      });

      expect(response).toEqual(newSessionResponse);
      expect(sessionsApi.startSession).toHaveBeenCalledWith(config, mockAccessToken);
      // Should have refreshed sessions after creation (initial load + refresh)
      expect(sessionsApi.getSessions).toHaveBeenCalledTimes(2);
    });

    it("should handle create session error", async () => {
      vi.mocked(sessionsApi.startSession).mockRejectedValue(
        new Error("Failed to create session")
      );

      const { result } = renderHook(() => useSessions(undefined, false));

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      const config = {
        workflow: "streamer" as const,
        captureMode: "av" as const,
      };

      await expect(result.current.createSession(config)).rejects.toThrow(
        "Failed to create session"
      );

      // Wait for error state to be updated
      await waitFor(() => {
        expect(result.current.error).toBe("Failed to create session");
      });
    });
  });

  describe("endSession", () => {
    it("should end a session and refresh list", async () => {
      vi.mocked(sessionsApi.endSession).mockResolvedValue({
        sessionId: "session-1",
        endedAt: Date.now(),
        duration: 3600000,
        clipCount: 5,
        outputCount: 10,
      });

      const { result } = renderHook(() => useSessions(undefined, false));

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      await act(async () => {
        await result.current.endSession("session-1");
      });

      expect(sessionsApi.endSession).toHaveBeenCalledWith("session-1", mockAccessToken);
      expect(sessionsApi.getSessions).toHaveBeenCalledTimes(2);
    });

    it("should handle end session error", async () => {
      vi.mocked(sessionsApi.endSession).mockRejectedValue(
        new Error("Session not found")
      );

      const { result } = renderHook(() => useSessions(undefined, false));

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      await expect(result.current.endSession("invalid-id")).rejects.toThrow(
        "Session not found"
      );

      // Wait for error state to be updated
      await waitFor(() => {
        expect(result.current.error).toBe("Session not found");
      });
    });
  });

  describe("updateSession", () => {
    it("should update session and refresh list", async () => {
      vi.mocked(sessionsApi.updateSession).mockResolvedValue(
        createMockApiSession({ id: "session-1", title: "Updated Title" })
      );

      const { result } = renderHook(() => useSessions(undefined, false));

