/**
 * Create a mock API response
 */
export function createMockResponse<T>(data: T, ok = true, status = 200) {
  return {
    ok,
    status,
    json: () => Promise.resolve(data),
    text: () => Promise.resolve(JSON.stringify(data)),
  } as Response;
}

/**
 * Create a mock session for testing
 */
export function createMockSession(overrides = {}) {
  return {
    id: "test-session-id",
    name: "Test Session",
    workflow: "content_creator",
    captureMode: "audio_video",
    status: "ended" as const,
    startedAt: new Date().toISOString(),
    endedAt: new Date().toISOString(),
    duration: "00:30:00",
    clipCount: 5,
    outputCount: 10,
    ...overrides,
  };
}

/**
 * Create a mock API session response
 */
export function createMockApiSession(overrides: Record<string, unknown> = {}) {
  return {
    id: "test-session-id",
    workflow: "streamer" as const,
    captureMode: "av" as const,
    title: "Test Session",
    participants: ["Host"],
    startedAt: new Date().toISOString(),
    endedAt: null,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    isActive: true,
    counts: {
      events: 100,
      outputs: 10,
      clips: 5,
    },
    ...overrides,
  };
}

/**
 * Mock the fetch function for a specific endpoint
 */
export function mockFetch(response: unknown, ok = true, status = 200) {
  (global.fetch as ReturnType<typeof vi.fn>).mockResolvedValueOnce(
    createMockResponse(response, ok, status)
  );
}

/**
 * Mock fetch to reject with an error
 */
export function mockFetchError(error: Error | string) {
  (global.fetch as ReturnType<typeof vi.fn>).mockRejectedValueOnce(
    typeof error === "string" ? new Error(error) : error
  );
}

"use client";

import { Suspense, useEffect, useState } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { AuthLayout } from '@/components/auth/AuthLayout';
import { logger } from "@/lib/logger";
import { API_CONFIG } from '@/lib/config';

export default function OAuthCallbackPage() {
  return (
    <Suspense fallback={<AuthLayout title="Completing sign in" subtitle="Please wait..."><div className="animate-pulse h-32" /></AuthLayout>}>
      <OAuthCallbackContent />
    </Suspense>
  );
}

function OAuthCallbackContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const handleCallback = async () => {
      // Get tokens from URL params (set by backend redirect)
      const accessToken = searchParams.get('accessToken');
      const refreshToken = searchParams.get('refreshToken');
      const isNewUser = searchParams.get('isNewUser') === 'true';
      const errorParam = searchParams.get('error');

      if (errorParam) {
        setError(decodeURIComponent(errorParam));
        return;
      }

      if (!accessToken || !refreshToken) {
        setError('Missing authentication tokens');
        return;
      }

      try {
        // Store tokens in localStorage
        localStorage.setItem('fluxboard_access_token', accessToken);
        localStorage.setItem('fluxboard_refresh_token', refreshToken);
        localStorage.setItem('fluxboard_remember_me', 'true');

        // Calculate token expiry (default to 15 minutes)
        const expiryTime = Date.now() + 15 * 60 * 1000;
        localStorage.setItem('fluxboard_token_expiry', expiryTime.toString());

        // Fetch and store user data
        const response = await fetch(`${API_CONFIG.baseUrl}/api/v1/auth/me`, {
          headers: {
            'Authorization': `Bearer ${accessToken}`,
          },
        });

        if (response.ok) {
          const data = await response.json();
          if (data.success && data.data?.user) {
            localStorage.setItem('fluxboard_user', JSON.stringify(data.data.user));
          }
        }

        // Redirect to dashboard
        router.push('/dashboard');
      } catch (err) {
        logger.error('OAuth callback error:', err);
        setError('Failed to complete authentication');
      }
    };

    handleCallback();
  }, [router, searchParams]);

  if (error) {
    return (
      <AuthLayout
        title="Authentication failed"
        subtitle="There was a problem signing you in"
      >
        <div className="text-center space-y-4">
          <div className="w-16 h-16 mx-auto bg-red-500/10 rounded-full flex items-center justify-center">
            <svg className="w-8 h-8 text-red-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </div>

          <div className="space-y-2">
            <p className="text-sm text-neutral-300">
              {error}
            </p>
          </div>

          <div className="pt-4">
            <a
              href="/auth/login"
              className="inline-flex items-center justify-center w-full px-4 py-2.5 text-sm font-medium text-white bg-primary-500 hover:bg-primary-600 rounded-lg transition-colors"
            >
              Back to login
            </a>
          </div>
        </div>
      </AuthLayout>
    );
  }

  return (
    <AuthLayout
      title="Completing sign in"
      subtitle="Please wait while we finish setting up your account"
    >
      <div className="text-center space-y-4">
        <div className="w-16 h-16 mx-auto">
          <svg className="animate-spin h-16 w-16 text-primary-400" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
          </svg>
        </div>

        <p className="text-sm text-neutral-400">
          Authenticating...
        </p>
      </div>
    </AuthLayout>
  );
}

"use client";

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { AuthLayout } from '@/components/auth/AuthLayout';
import { Input } from '@/components/ui/Input';
import { Button } from '@/components/ui/Button';
import { forgotPassword } from '@/lib/api/auth';

export default function ForgotPasswordPage() {
  const router = useRouter();
  const [email, setEmail] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);

  const validateEmail = (email: string): boolean => {
    if (!email) {
      setError('Email is required');
      return false;
    }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      setError('Please enter a valid email address');
      return false;
    }
    return true;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!validateEmail(email)) {
      return;
    }

    setIsLoading(true);

    try {
      await forgotPassword({ email });
      setSuccess(true);
    } catch (err) {
      // The API returns a generic message to prevent email enumeration
      // So we'll always show success to the user
      setSuccess(true);
    } finally {
      setIsLoading(false);
    }
  };

  if (success) {
    return (
      <AuthLayout
        title="Check your email"
        subtitle="We've sent you a password reset link"
      >
        <div className="text-center space-y-4">
          <div className="w-16 h-16 mx-auto bg-primary-500/10 rounded-full flex items-center justify-center">
            <svg className="w-8 h-8 text-primary-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
            </svg>
          </div>

          <div className="space-y-2">
            <p className="text-sm text-neutral-300">
              If an account exists for <span className="font-medium text-neutral-100">{email}</span>,
              you will receive a password reset link shortly.
            </p>
            <p className="text-xs text-neutral-500">
              The link will expire in 1 hour.
            </p>
          </div>

          <div className="pt-4 space-y-3">
            <Button
              onClick={() => router.push('/auth/login')}
              fullWidth
            >
              Back to login
            </Button>

            <button
              onClick={() => {
                setSuccess(false);
                setEmail('');
              }}
              className="w-full text-sm text-neutral-400 hover:text-neutral-300 transition-colors"
            >
              Try a different email
            </button>
          </div>
        </div>
      </AuthLayout>
    );
  }

  return (
    <AuthLayout
      title="Forgot password?"
      subtitle="No worries, we'll send you reset instructions"
    >
      {error && (
        <div className="mb-6 p-4 bg-red-500/10 border border-red-500/20 rounded-lg">
          <p className="text-sm text-red-400">{error}</p>
        </div>
      )}

      <form onSubmit={handleSubmit} className="space-y-6">
        <Input
          label="Email address"
          type="email"
          value={email}
          onChange={(e) => {
            setEmail(e.target.value);
            setError('');
          }}
          placeholder="you@example.com"
          autoComplete="email"
          required
          fullWidth
          disabled={isLoading}
          helperText="Enter the email address associated with your account"
        />

        <Button
          type="submit"
          fullWidth
          disabled={isLoading}
        >
          {isLoading ? 'Sending reset link...' : 'Send reset link'}
        </Button>
      </form>

      <div className="mt-6 text-center">
        <a
          href="/auth/login"
          className="text-sm text-neutral-400 hover:text-neutral-300 transition-colors inline-flex items-center gap-2"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
          </svg>
          Back to login
        </a>
      </div>
    </AuthLayout>
  );
}

