                <div className="mt-4">
                  <p className="text-xs text-text-dim mb-2">Suggested phrases:</p>
                  <div className="flex flex-wrap gap-2">
                    {SUGGESTED_PHRASES.filter(
                      (p) => !triggerConfig.audioTriggers.some((t) => t.phrase.toLowerCase() === p.toLowerCase())
