/**
 * Calculate live duration from session start time to now
 */
function calculateLiveDuration(startedAt: string): string {
  const start = new Date(startedAt).getTime();
  const now = Date.now();
  const durationMs = now - start;

  const seconds = Math.floor(durationMs / 1000);
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const secs = seconds % 60;

  return `${hours}:${minutes.toString().padStart(2, "0")}:${secs.toString().padStart(2, "0")}`;
}

function formatReplayTimestamp(ts?: number | null): string {
  if (!ts) return "Never";
  return new Date(ts).toLocaleTimeString();
}

// ============================================================
// Post Card Component with Edit/Copy/Regenerate functionality
// ============================================================

interface PostCardProps {
  output: Output;
  onApprove: (id: string) => Promise<void>;
  onDelete: (id: string) => Promise<void>;
  onUpdate: (id: string, updates: { title?: string; text?: string }) => Promise<void>;
}

function PostCard({ output, onApprove, onDelete, onUpdate }: PostCardProps) {
  const [isEditing, setIsEditing] = useState(false);
  const [editTitle, setEditTitle] = useState(output.title || "");
  const [editText, setEditText] = useState(output.text);
  const [isSaving, setIsSaving] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isRegenerating, setIsRegenerating] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [showRegenerateOptions, setShowRegenerateOptions] = useState(false);
  const [regenerateInstructions, setRegenerateInstructions] = useState("");

  const platformConfig = PLATFORM_CONFIG[output.platform];

  // Reset edit state when output changes
  useEffect(() => {
    setEditTitle(output.title || "");
    setEditText(output.text);
  }, [output.title, output.text]);

  // Handle copy to clipboard
  const handleCopy = useCallback(async () => {
    try {
      const textToCopy = output.title
        ? `${output.title}\n\n${output.text}`
        : output.text;

      await navigator.clipboard.writeText(textToCopy);
      setCopySuccess(true);

      // Reset success state after 2 seconds
      setTimeout(() => {
        setCopySuccess(false);
      }, 2000);
    } catch (err) {
      logger.error("Failed to copy to clipboard:", err);
      // Fallback for older browsers
      try {
        const textArea = document.createElement("textarea");
        textArea.value = output.title
          ? `${output.title}\n\n${output.text}`
          : output.text;
        textArea.style.position = "fixed";
        textArea.style.left = "-999999px";
        document.body.appendChild(textArea);
        textArea.select();
        document.execCommand("copy");
        document.body.removeChild(textArea);
        setCopySuccess(true);
        setTimeout(() => setCopySuccess(false), 2000);
      } catch {
        logger.error("Fallback copy also failed");
      }
    }
  }, [output.title, output.text]);

  // Handle edit mode toggle
  const handleStartEdit = useCallback(() => {
    setEditTitle(output.title || "");
    setEditText(output.text);
    setIsEditing(true);
  }, [output.title, output.text]);

  // Handle cancel edit
  const handleCancelEdit = useCallback(() => {
    setEditTitle(output.title || "");
    setEditText(output.text);
    setIsEditing(false);
  }, [output.title, output.text]);

  // Handle save edit
  const handleSaveEdit = useCallback(async () => {
    if (isSaving) return;

    setIsSaving(true);
    try {
      await onUpdate(output.id, {
        title: editTitle || undefined,
        text: editText,
      });
      setIsEditing(false);
    } catch (err) {
      logger.error("Failed to save edit:", err);
    } finally {
      setIsSaving(false);
    }
  }, [output.id, editTitle, editText, onUpdate, isSaving]);

  // Handle delete with confirmation
  const handleDelete = useCallback(async () => {
    if (isDeleting) return;

    setIsDeleting(true);
    try {
      await onDelete(output.id);
    } catch (err) {
      logger.error("Failed to delete:", err);
    } finally {
      setIsDeleting(false);
      setShowDeleteConfirm(false);
    }
  }, [output.id, onDelete, isDeleting]);

  // Handle regenerate content
  const handleRegenerate = useCallback(async (instructions?: string) => {
    if (isRegenerating) return;

    setIsRegenerating(true);
    try {
      // Import regenerateOutput dynamically to avoid circular dependencies
      const { regenerateOutput } = await import("@/lib/api/outputs");

      // Call API to regenerate content with AI
      const regeneratedOutput = await regenerateOutput(output.id, {
        instructions: instructions || undefined,
      });

      // Update parent component with new output
      await onUpdate(output.id, {
        text: regeneratedOutput.text,
        title: regeneratedOutput.title || undefined,
      });

      // Close options modal and clear instructions
      setShowRegenerateOptions(false);
      setRegenerateInstructions("");

      logger.info("Output regenerated successfully", {
        outputId: output.id,
        previousLength: output.text.length,
        newLength: regeneratedOutput.text.length,
        hadInstructions: !!instructions,
      });
    } catch (err) {
      logger.error("Failed to regenerate:", err);
      // Show user-friendly error message
      alert("Failed to regenerate content. Please try again.");
    } finally {
      setIsRegenerating(false);
    }
  }, [output.id, output.text.length, onUpdate, isRegenerating]);

  // Regenerate options modal
  if (showRegenerateOptions) {
    return (
      <div className="rounded-xl border border-purple/50 bg-surface p-4">
        <div className="mb-3 flex items-center gap-2">
          <span className="text-purple">
            <SparklesIcon className="h-4 w-4" />
          </span>
          <span className="text-xs font-medium text-text-muted">
            Regenerate with AI - Advanced Options
          </span>
        </div>

        {/* Instructions input */}
        <label className="mb-2 block text-xs text-text-muted">
          Custom Instructions (Optional)
        </label>
        <textarea
          value={regenerateInstructions}
          onChange={(e) => setRegenerateInstructions(e.target.value)}
          placeholder="e.g., Make it more casual, Add emojis, Focus on benefits..."
          rows={3}
          maxLength={1000}
          className="mb-2 w-full resize-none rounded-lg border border-stroke bg-bg-2 px-3 py-2 text-sm text-text placeholder:text-text-dim focus:border-purple focus:outline-none focus:ring-1 focus:ring-purple"
        />
        <div className="mb-3 flex justify-between text-xs text-text-dim">
          <span>Provide specific instructions for how to modify the content</span>
          <span>{regenerateInstructions.length}/1000</span>
        </div>

        {/* Action buttons */}
        <div className="flex justify-end gap-2">
          <button
            type="button"
            onClick={() => {
              setShowRegenerateOptions(false);
              setRegenerateInstructions("");
            }}
            disabled={isRegenerating}
            className="rounded-lg px-3 py-1.5 text-xs font-medium text-text-muted transition-colors hover:bg-surface-hover disabled:opacity-50"
          >
            Cancel
          </button>
          <button
            type="button"
            onClick={() => handleRegenerate(regenerateInstructions || undefined)}
            disabled={isRegenerating}
            className="flex items-center gap-1.5 rounded-lg bg-purple px-3 py-1.5 text-xs font-medium text-white transition-colors hover:bg-purple/90 disabled:opacity-50"
          >
            {isRegenerating ? (
              <>
                <LoadingSpinner className="h-3 w-3" />
                Regenerating...
              </>
            ) : (
              <>
                <SparklesIcon className="h-3 w-3" />
                Regenerate
              </>
            )}
          </button>
        </div>
      </div>
    );
  }

  if (isEditing) {
    return (
      <div className="rounded-xl border border-purple/50 bg-surface p-4">
        <div className="mb-3 flex items-center gap-2">
          <span style={{ color: platformConfig.color }}>
            <platformConfig.Icon className="h-4 w-4" />
          </span>
          <span className="text-xs font-medium text-text-muted">
            Editing {platformConfig.name} Post
          </span>
        </div>

        {/* Title input */}
        <input
          type="text"
          value={editTitle}
          onChange={(e) => setEditTitle(e.target.value)}
          placeholder="Title (optional)"
          className="mb-2 w-full rounded-lg border border-stroke bg-bg-2 px-3 py-2 text-sm text-text placeholder:text-text-dim focus:border-purple focus:outline-none focus:ring-1 focus:ring-purple"
        />

        {/* Text input */}
        <textarea
          value={editText}
          onChange={(e) => setEditText(e.target.value)}
          placeholder="Post content"
          rows={4}
          className="mb-3 w-full resize-none rounded-lg border border-stroke bg-bg-2 px-3 py-2 text-sm text-text placeholder:text-text-dim focus:border-purple focus:outline-none focus:ring-1 focus:ring-purple"
        />

        {/* Action buttons */}
        <div className="flex justify-end gap-2">
          <button
            type="button"
            onClick={handleCancelEdit}
            disabled={isSaving}
            className="rounded-lg px-3 py-1.5 text-xs font-medium text-text-muted transition-colors hover:bg-surface-hover disabled:opacity-50"
          >
            Cancel
          </button>
          <button
            type="button"
            onClick={handleSaveEdit}
            disabled={isSaving || !editText.trim()}
            className="flex items-center gap-1.5 rounded-lg bg-purple px-3 py-1.5 text-xs font-medium text-white transition-colors hover:bg-purple/90 disabled:opacity-50"
          >
            {isSaving ? (
              <>
                <LoadingSpinner className="h-3 w-3" />
                Saving...
              </>
            ) : (
              <>
                <CheckIcon className="h-3 w-3" />
                Save
              </>
            )}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="rounded-xl border border-stroke bg-surface p-4 transition-colors hover:bg-surface-hover">
      {/* Header */}
      <div className="mb-3 flex items-center gap-2">
        <span style={{ color: platformConfig.color }}>
          <platformConfig.Icon className="h-4 w-4" />
        </span>
        <span className="text-xs font-medium text-text-muted">
          {platformConfig.name}
        </span>
        <Badge
          variant={
            output.status === "approved"
              ? "success"
              : output.status === "published"
              ? "teal"
              : "default"
          }
          className="ml-auto text-xs"
        >
          {output.status}
        </Badge>
      </div>

      {/* Content */}
      {output.title && (
        <h4 className="mb-1 text-sm font-medium text-text">
          {output.title}
        </h4>
      )}
      <p className="line-clamp-3 text-sm text-text">
        {output.text}
      </p>

      {/* Footer */}
      <div className="mt-3 flex items-center justify-between">
        <span className="text-xs text-text-dim">
          {output.formattedDate}
        </span>

        <div className="flex gap-1">
          {/* Copy button */}
          <button
            type="button"
            onClick={handleCopy}
            className={cn(
              "rounded p-1 transition-colors",
              copySuccess
                ? "bg-success/10 text-success"
                : "text-text-muted hover:bg-surface hover:text-text"
            )}
            title={copySuccess ? "Copied!" : "Copy to clipboard"}
          >
            {copySuccess ? (
              <CheckIcon className="h-4 w-4" />
            ) : (
              <ClipboardIcon className="h-4 w-4" />
            )}
          </button>

          {/* Edit button */}
          <button
            type="button"
            onClick={handleStartEdit}
            className="rounded p-1 text-text-muted transition-colors hover:bg-surface hover:text-text"
            title="Edit post"
          >
            <PencilIcon className="h-4 w-4" />
          </button>

          {/* Regenerate button - shows options on shift+click, quick regenerate otherwise */}
          <button
            type="button"
            onClick={(e) => {
              if (e.shiftKey) {
                setShowRegenerateOptions(true);
              } else {
                handleRegenerate();
              }
            }}
            disabled={isRegenerating}
            className="rounded p-1 text-purple transition-colors hover:bg-purple/10 disabled:opacity-50"
            title="Regenerate with AI (Shift+Click for options)"
          >
            {isRegenerating ? (
              <LoadingSpinner className="h-4 w-4" />
            ) : (
              <SparklesIcon className="h-4 w-4" />
            )}
          </button>

          {/* Approve button (only for drafts) */}
          {output.status === "draft" && (
            <button
              type="button"
              onClick={() => onApprove(output.id)}
              className="rounded p-1 text-success transition-colors hover:bg-success/10"
              title="Approve"
            >
              <CheckIcon className="h-4 w-4" />
            </button>
          )}

          {/* Delete button with confirmation */}
          {showDeleteConfirm ? (
            <div className="flex items-center gap-1">
              <button
                type="button"
                onClick={handleDelete}
                disabled={isDeleting}
                className="rounded p-1 text-error transition-colors hover:bg-error/10 disabled:opacity-50"
                title="Confirm delete"
              >
                {isDeleting ? (
                  <LoadingSpinner className="h-4 w-4" />
                ) : (
                  <CheckIcon className="h-4 w-4" />
                )}
              </button>
              <button
                type="button"
                onClick={() => setShowDeleteConfirm(false)}
                disabled={isDeleting}
                className="rounded p-1 text-text-muted transition-colors hover:bg-surface hover:text-text disabled:opacity-50"
                title="Cancel"
              >
                <XMarkIcon className="h-4 w-4" />
              </button>
            </div>
          ) : (
            <button
              type="button"
              onClick={() => setShowDeleteConfirm(true)}
              className="rounded p-1 text-error transition-colors hover:bg-error/10"
              title="Delete"
            >
              <TrashIcon className="h-4 w-4" />
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

