                </CardHeader>
              <CardContent>
                {/* Live Video Preview */}
                <div className="relative">
                  <LiveVideoPreview
                    webrtcUrl={videoStatus?.webrtcUrl}
                    hlsUrl={videoStatus?.hlsUrl}
                    isStreamActive={videoStatus?.isStreaming ?? false}
                    onConnectionChange={(connected) => {
                      // Optional: sync with OBS connection state if needed
