                />
              </svg>
            </div>

            {/* Title */}
            <h1 className="mb-2 text-2xl font-bold text-white">
              Something went wrong
            </h1>

            {/* Description */}
            <p className="mb-8 text-gray-400">
              An unexpected error has occurred. Please try again.
