export { ScriptStudioActionPanel };

"use client";

import { useState, useCallback, useEffect, useRef } from "react";
import type {
  AgentAction,
  ActionStatus,
  ActionExecution,
  ActionResult,
  ClipTitleResult,
  SocialPostResult,
  ClipMomentResult,
} from "./types";
import {
  getContentCreatorActions,
  getContentCreatorAutoActions,
} from "./types";
import { logger } from "@/lib/logger";

// ============================================================
// Action Hook State
// ============================================================

interface UseActionsState {
  executions: ActionExecution[];
  autoTriggerEnabled: Record<string, boolean>;
  cooldowns: Record<string, number>;
  clipTitles: ClipTitleResult[];
  socialPosts: SocialPostResult[];
  clipMoments: ClipMomentResult[];
  isExpanded: boolean;
}

interface UseActionsReturn {
  // State
  actions: AgentAction[];
  autoActions: AgentAction[];
  executions: ActionExecution[];
  isExpanded: boolean;
  clipTitles: ClipTitleResult[];
  socialPosts: SocialPostResult[];
  clipMoments: ClipMomentResult[];

  // Actions
  executeAction: (actionId: string, inputs?: Record<string, unknown>) => Promise<void>;
  cancelAction: (executionId: string) => void;
  toggleAutoTrigger: (actionId: string) => void;
  isAutoTriggerEnabled: (actionId: string) => boolean;
  isOnCooldown: (actionId: string) => boolean;
  getCooldownRemaining: (actionId: string) => number;
  getExecutionStatus: (actionId: string) => ActionStatus | null;
  getActiveExecutions: () => ActionExecution[];
  setExpanded: (expanded: boolean) => void;
  toggleExpanded: () => void;
  clearResults: () => void;

  // Result handlers
  addClipTitle: (result: ClipTitleResult) => void;
  addSocialPost: (result: SocialPostResult) => void;
  addClipMoment: (result: ClipMomentResult) => void;
  updateSocialPostStatus: (id: string, status: SocialPostResult["status"]) => void;
}

// ============================================================
// useActions Hook
// ============================================================

export function useActions(): UseActionsReturn {
  const [state, setState] = useState<UseActionsState>({
    executions: [],
    autoTriggerEnabled: {},
    cooldowns: {},
    clipTitles: [],
    socialPosts: [],
    clipMoments: [],
    isExpanded: true,
  });

  const cooldownTimers = useRef<Record<string, NodeJS.Timeout>>({});

  // Get all actions for Content Creator
  const actions = getContentCreatorActions();
  const autoActions = getContentCreatorAutoActions();

  // Initialize auto-trigger settings
  useEffect(() => {
    const initialAutoTrigger: Record<string, boolean> = {};
    autoActions.forEach((action) => {
      // Auto-trigger is enabled by default for auto actions
      initialAutoTrigger[action.actionId] = true;
    });
    setState((prev) => ({
      ...prev,
      autoTriggerEnabled: { ...initialAutoTrigger, ...prev.autoTriggerEnabled },
    }));
  }, [autoActions]);

  // Generate unique execution ID
  const generateExecutionId = useCallback(() => {
    return `exec_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }, []);

  // Execute an action
  const executeAction = useCallback(
    async (actionId: string, inputs?: Record<string, unknown>) => {
      const action = actions.find((a) => a.actionId === actionId);
      if (!action) {
        logger.error(`Action not found: ${actionId}`);
        return;
      }

      // Check cooldown
      if (state.cooldowns[actionId] && state.cooldowns[actionId] > Date.now()) {
        logger.warn(`Action ${actionId} is on cooldown`);
        return;
      }

      const executionId = generateExecutionId();
      const execution: ActionExecution = {
        id: executionId,
        actionId,
        status: "processing",
        startedAt: Date.now(),
        progress: 0,
      };

      // Add execution to state
      setState((prev) => ({
        ...prev,
        executions: [...prev.executions, execution],
      }));

      try {
        // Simulate action processing (replace with actual API call)
        await simulateActionExecution(action, inputs, (progress) => {
          setState((prev) => ({
            ...prev,
            executions: prev.executions.map((e) =>
              e.id === executionId ? { ...e, progress } : e
            ),
          }));
        });

        // Mark as success
        setState((prev) => ({
          ...prev,
          executions: prev.executions.map((e) =>
            e.id === executionId
              ? { ...e, status: "success", completedAt: Date.now(), progress: 100 }
              : e
          ),
        }));

        // Set cooldown if defined
        if (action.cooldownMs) {
          const cooldownEnd = Date.now() + action.cooldownMs;
          setState((prev) => ({
            ...prev,
            cooldowns: { ...prev.cooldowns, [actionId]: cooldownEnd },
          }));

          // Clear cooldown after timeout
          if (cooldownTimers.current[actionId]) {
            clearTimeout(cooldownTimers.current[actionId]);
          }
          cooldownTimers.current[actionId] = setTimeout(() => {
            setState((prev) => {
              const newCooldowns = { ...prev.cooldowns };
              delete newCooldowns[actionId];
              return { ...prev, cooldowns: newCooldowns };
            });
          }, action.cooldownMs);
        }
      } catch (error) {
        // Mark as failed
        setState((prev) => ({
          ...prev,
          executions: prev.executions.map((e) =>
            e.id === executionId
              ? {
                  ...e,
                  status: "failed",
                  completedAt: Date.now(),
                  error: error instanceof Error ? error.message : "Unknown error",
                }
              : e
          ),
        }));
      }
    },
    [actions, state.cooldowns, generateExecutionId]
  );

  // Cancel an action
  const cancelAction = useCallback((executionId: string) => {
    setState((prev) => ({
      ...prev,
      executions: prev.executions.map((e) =>
        e.id === executionId && e.status === "processing"
          ? { ...e, status: "cancelled", completedAt: Date.now() }
          : e
      ),
    }));
  }, []);

  // Toggle auto-trigger for an action
  const toggleAutoTrigger = useCallback((actionId: string) => {
    setState((prev) => ({
      ...prev,
      autoTriggerEnabled: {
        ...prev.autoTriggerEnabled,
        [actionId]: !prev.autoTriggerEnabled[actionId],
      },
    }));
  }, []);

  // Check if auto-trigger is enabled
  const isAutoTriggerEnabled = useCallback(
    (actionId: string) => {
      return state.autoTriggerEnabled[actionId] ?? false;
    },
    [state.autoTriggerEnabled]
  );

  // Check if action is on cooldown
  const isOnCooldown = useCallback(
    (actionId: string) => {
      const cooldownEnd = state.cooldowns[actionId];
      return cooldownEnd ? cooldownEnd > Date.now() : false;
    },
    [state.cooldowns]
  );

  // Get cooldown remaining time
  const getCooldownRemaining = useCallback(
    (actionId: string) => {
      const cooldownEnd = state.cooldowns[actionId];
      if (!cooldownEnd) return 0;
      const remaining = cooldownEnd - Date.now();
      return remaining > 0 ? remaining : 0;
    },
    [state.cooldowns]
  );

  // Get execution status for an action
  const getExecutionStatus = useCallback(
    (actionId: string): ActionStatus | null => {
      const execution = state.executions
        .filter((e) => e.actionId === actionId)
        .sort((a, b) => b.startedAt - a.startedAt)[0];
      return execution?.status ?? null;
    },
    [state.executions]
  );

  // Get active executions
  const getActiveExecutions = useCallback(() => {
    return state.executions.filter((e) => e.status === "processing");
  }, [state.executions]);

  // Set expanded state
  const setExpanded = useCallback((expanded: boolean) => {
    setState((prev) => ({ ...prev, isExpanded: expanded }));
  }, []);

  // Toggle expanded state
  const toggleExpanded = useCallback(() => {
    setState((prev) => ({ ...prev, isExpanded: !prev.isExpanded }));
  }, []);

  // Clear all results
  const clearResults = useCallback(() => {
    setState((prev) => ({
      ...prev,
      executions: [],
      clipTitles: [],
      socialPosts: [],
      clipMoments: [],
    }));
  }, []);

  // Add clip title result
  const addClipTitle = useCallback((result: ClipTitleResult) => {
    setState((prev) => ({
      ...prev,
      clipTitles: [...prev.clipTitles, result],
    }));
  }, []);

  // Add social post result
  const addSocialPost = useCallback((result: SocialPostResult) => {
    setState((prev) => ({
      ...prev,
      socialPosts: [...prev.socialPosts, result],
    }));
  }, []);

  // Add clip moment result
  const addClipMoment = useCallback((result: ClipMomentResult) => {
    setState((prev) => ({
      ...prev,
      clipMoments: [...prev.clipMoments, result],
    }));
  }, []);

  // Update social post status
  const updateSocialPostStatus = useCallback(
    (id: string, status: SocialPostResult["status"]) => {
      setState((prev) => ({
        ...prev,
        socialPosts: prev.socialPosts.map((post) =>
          post.id === id ? { ...post, status } : post
        ),
      }));
    },
    []
  );

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      Object.values(cooldownTimers.current).forEach(clearTimeout);
    };
  }, []);

  return {
    actions,
    autoActions,
    executions: state.executions,
    isExpanded: state.isExpanded,
    clipTitles: state.clipTitles,
    socialPosts: state.socialPosts,
    clipMoments: state.clipMoments,
    executeAction,
    cancelAction,
    toggleAutoTrigger,
    isAutoTriggerEnabled,
    isOnCooldown,
    getCooldownRemaining,
    getExecutionStatus,
    getActiveExecutions,
    setExpanded,
    toggleExpanded,
    clearResults,
    addClipTitle,
    addSocialPost,
    addClipMoment,
    updateSocialPostStatus,
  };
}

// ============================================================
// Simulation Helper (Replace with actual API calls)
// ============================================================

async function simulateActionExecution(
  action: AgentAction,
  _inputs?: Record<string, unknown>,
  onProgress?: (progress: number) => void
): Promise<ActionResult> {
  // Simulate processing time based on token estimate
  const processingTimes = {
    low: 1000,
    medium: 2000,
    high: 4000,
  };

  const totalTime = processingTimes[action.estimatedTokens];
  const steps = 10;
  const stepTime = totalTime / steps;

  for (let i = 1; i <= steps; i++) {
    await new Promise((resolve) => setTimeout(resolve, stepTime));
    onProgress?.(Math.round((i / steps) * 100));
  }

  return {
    actionId: action.actionId,
    status: "success",
    timestamp: Date.now(),
    data: {},
    confidence: 0.85,
  };
}

export default useActions;

"use client";

import { useState, useEffect, useCallback } from "react";
import { Badge, Button, Card } from "@/components/ui";
import { ClipQueueItemCard, type ClipQueueItem } from "./ClipQueueItemCard";
import { logger } from "@/lib/logger";
import { API_CONFIG } from "@/lib/config";
import { getHealth } from "@/lib/api/health";

interface ClipQueueDashboardProps {
  sessionId: string;
  isCollapsed?: boolean;
  onToggleCollapse?: () => void;
  /** Whether OBS is actively streaming. Clip queue only activates when true. */
  isStreaming?: boolean;
}

type FilterStatus = "all" | "pending" | "recording" | "processing" | "completed" | "failed";

interface ClipQueueStats {
  total: number;
  pending: number;
  recording: number;
  processing: number;
  completed: number;
  failed: number;
}

interface ReplayBufferState {
  active: boolean;
  lastSavedAt?: number | null;
  lastSavedPath?: string | null;
  lastSaveRequestedAt?: number | null;
  lastError?: string | null;
  outputDir?: string | null;
}

export function ClipQueueDashboard({
  sessionId,
  isCollapsed = false,
  onToggleCollapse,
  isStreaming = false,
}: ClipQueueDashboardProps) {
  const [items, setItems] = useState<ClipQueueItem[]>([]);
  const [stats, setStats] = useState<ClipQueueStats>({
    total: 0,
    pending: 0,
    recording: 0,
    processing: 0,
    completed: 0,
    failed: 0,
  });
  const [filter, setFilter] = useState<FilterStatus>("all");
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [replayBuffer, setReplayBuffer] = useState<ReplayBufferState | null>(null);
  const [isSavingReplay, setIsSavingReplay] = useState(false);

  const apiBase = API_CONFIG.desktopApiUrl;
  const wsBase = API_CONFIG.desktopWsUrl;

  const formatReplayTimestamp = (ts?: number | null) => {
    if (!ts) return "Never";
    return new Date(ts).toLocaleTimeString();
  };

  const computeStats = useCallback((queueItems: ClipQueueItem[]): ClipQueueStats => {
    return queueItems.reduce<ClipQueueStats>(
      (acc, item) => {
        acc.total += 1;
        acc[item.status as keyof ClipQueueStats] += 1;
        return acc;
      },
      { total: 0, pending: 0, recording: 0, processing: 0, completed: 0, failed: 0 }
    );
  }, []);

  // Fetch queue items
  const fetchItems = useCallback(async () => {
    try {
      const response = await fetch(`${apiBase}/api/sessions/${sessionId}/clip-queue`);
      if (!response.ok) throw new Error("Failed to fetch clip queue");

      const data = await response.json();
      const nextItems = data.items || [];
      setItems(nextItems);
      setStats(data.stats || computeStats(nextItems));
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load queue");
    } finally {
      setIsLoading(false);
    }
  }, [sessionId, apiBase, computeStats]);

  // Fetch replay buffer status
  const fetchReplayStatus = useCallback(async () => {
    try {
      const health = await getHealth();
      setReplayBuffer(health.components?.replayBuffer ?? null);
    } catch {
      setReplayBuffer(null);
    }
  }, []);

  // Subscribe to WebSocket updates (keep connection stable regardless of streaming state)
  useEffect(() => {
    if (!sessionId) {
      setIsLoading(false);
      return;
    }

    fetchItems();

    // Connect to WebSocket for real-time updates
    const ws = new WebSocket(wsBase);

    ws.onopen = () => {
      logger.debug("[clip-queue] WebSocket connected");
    };

    ws.onmessage = (event) => {
      try {
        const data = JSON.parse(event.data);

        if (data.type === "CLIP_QUEUE_UPDATED" && data.sessionId === sessionId) {
          const payload = data.payload;

          setItems((prevItems) => {
            const existingIndex = prevItems.findIndex(
              (item) => item.id === payload.queueItemId
            );

            const updatedItem: ClipQueueItem = {
              id: payload.queueItemId,
              sessionId,
              status: payload.status,
              triggerType: payload.triggerType,
              triggerSource: payload.triggerSource,
              t0: payload.t0,
              t1: payload.t1,
              clipId: payload.clipId,
              thumbnailPath: payload.thumbnailPath,
              title: payload.title,
              errorMessage: payload.errorMessage,
              createdAt: new Date().toISOString(),
            };

            let newItems: ClipQueueItem[];
            if (existingIndex >= 0) {
              newItems = [...prevItems];
              newItems[existingIndex] = updatedItem;
            } else {
              newItems = [updatedItem, ...prevItems];
            }

            setStats(computeStats(newItems));
            return newItems;
          });
        }
      } catch {
        // Ignore parse errors
      }
    };

    ws.onerror = () => {
      logger.error("[clip-queue] WebSocket error");
    };

    ws.onclose = () => {
      logger.debug("[clip-queue] WebSocket closed");
    };

    return () => {
      ws.close();
    };
  }, [sessionId, wsBase, fetchItems, computeStats]);

  // Poll replay buffer status
  useEffect(() => {
    fetchReplayStatus();
    const interval = setInterval(fetchReplayStatus, 5000);
    return () => clearInterval(interval);
  }, [fetchReplayStatus]);

  // Handle item actions
  const handleRetry = async (itemId: string) => {
    try {
      const response = await fetch(`${apiBase}/api/clip-queue/${itemId}/retry`, {
        method: "POST",
      });
      if (!response.ok) throw new Error("Failed to retry");
      fetchItems();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to retry");
    }
  };

  const handleDelete = async (itemId: string) => {
    try {
      const response = await fetch(`${apiBase}/api/clip-queue/${itemId}`, {
        method: "DELETE",
      });
      if (!response.ok) throw new Error("Failed to delete");
      setItems((prev) => prev.filter((item) => item.id !== itemId));
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to delete");
    }
  };

  const handleUpdateTitle = async (itemId: string, title: string) => {
    try {
      const response = await fetch(`${apiBase}/api/clip-queue/${itemId}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ title }),
      });
      if (!response.ok) throw new Error("Failed to update");
      setItems((prev) =>
        prev.map((item) => (item.id === itemId ? { ...item, title } : item))
      );
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to update");
    }
  };

  const handleSaveReplay = async () => {
    if (isSavingReplay) return;
    try {
      setIsSavingReplay(true);
      const response = await fetch(`${apiBase}/api/obs/replay/save`, { method: "POST" });
      if (!response.ok) throw new Error("Failed to save replay buffer");
      await fetchReplayStatus();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to save replay buffer");
    } finally {
      setIsSavingReplay(false);
    }
  };

  // Filter items
  const filteredItems = items.filter((item) => {
    if (filter === "all") return true;
    return item.status === filter;
  });

  // Check for active recording
  const activeRecording = items.find(
    (item) => item.status === "recording"
  );

  if (isCollapsed) {
    return (
      <div className="fixed right-0 top-1/2 -translate-y-1/2 z-40">
        <button
          onClick={onToggleCollapse}
          className="flex items-center gap-2 px-3 py-4 bg-surface border border-stroke rounded-l-lg shadow-lg hover:bg-surface-hover transition-colors"
          title="Expand Clip Queue"
        >
          <svg
            className="h-5 w-5 text-text"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
            strokeWidth={2}
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              d="M15 19l-7-7 7-7"
            />
          </svg>
          {stats.total > 0 && (
            <Badge variant="teal" className="text-xs">
              {stats.total}
            </Badge>
          )}
        </button>
      </div>
    );
  }

  return (
    <div className="fixed right-0 top-0 bottom-0 w-80 bg-bg-0 border-l border-stroke shadow-xl z-40 flex flex-col">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-stroke bg-surface">
        <div className="flex items-center gap-2">
          <svg
            className="h-5 w-5 text-teal"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
            strokeWidth={2}
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"
            />
          </svg>
          <h3 className="text-sm font-semibold text-text">Clip Queue</h3>
          <Badge variant="default" className="text-xs">
            {stats.total}
          </Badge>
        </div>
        <button
          onClick={onToggleCollapse}
          className="p-1 hover:bg-stroke rounded transition-colors"
          title="Collapse"
        >
          <svg
            className="h-5 w-5 text-text-dim"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
            strokeWidth={2}
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              d="M9 5l7 7-7 7"
            />
          </svg>
        </button>
      </div>

      {/* Replay Buffer Status */}
      {replayBuffer && (
        <div className="mx-4 mt-3 p-3 rounded-lg border border-stroke bg-bg-0">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Badge variant={replayBuffer.active ? "success" : "default"} className="text-xs">
                Replay {replayBuffer.active ? "Active" : "Inactive"}
              </Badge>
              <span className="text-xs text-text-dim">
                Last save: {formatReplayTimestamp(replayBuffer.lastSavedAt)}
              </span>
            </div>
            <Button
              size="sm"
              variant="outline"
              onClick={handleSaveReplay}
              disabled={isSavingReplay}
            >
              {isSavingReplay ? "Saving..." : "Save"}
            </Button>
          </div>
          {replayBuffer.lastError && (
            <p className="mt-2 text-xs text-error">Error: {replayBuffer.lastError}</p>
          )}
          {!replayBuffer.active && (
            <p className="mt-2 text-xs text-warning">
              Replay buffer is inactive. Enable it in OBS to capture clips.
            </p>
          )}
        </div>
      )}

      {/* Active Recording Banner */}
      {activeRecording && (
        <div className="mx-4 mt-4 p-3 rounded-lg bg-error/10 border border-error/30 animate-pulse">
          <div className="flex items-center gap-2">
            <span className="h-2 w-2 rounded-full bg-error animate-pulse" />
            <span className="text-sm font-medium text-error">Recording</span>
          </div>
          <p className="text-xs text-error/80 mt-1">
            {activeRecording.title || activeRecording.triggerSource}
          </p>
          <p className="text-xs text-text-dim mt-1">
            Started at {activeRecording.t0.toFixed(1)}s
          </p>
        </div>
      )}

      {/* Filter Tabs */}
      <div className="flex gap-1 p-2 border-b border-stroke overflow-x-auto">
        {(["all", "pending", "processing", "completed", "failed"] as FilterStatus[]).map(
          (status) => {
            const count =
              status === "all" ? stats.total : stats[status as keyof ClipQueueStats];
            return (
              <button
                key={status}
                onClick={() => setFilter(status)}
                className={`
                  px-3 py-1.5 text-xs font-medium rounded-lg whitespace-nowrap transition-colors
                  ${
                    filter === status
                      ? "bg-teal text-white"
                      : "bg-surface text-text-muted hover:bg-surface-hover"
                  }
                `}
              >
                {status.charAt(0).toUpperCase() + status.slice(1)}
                {count > 0 && (
                  <span className="ml-1 opacity-70">({count})</span>
                )}
              </button>
            );
          }
        )}
      </div>

      {/* Error Banner */}
      {error && (
        <div className="mx-4 mt-2 p-2 rounded bg-error/10 border border-error/30">
          <p className="text-xs text-error">{error}</p>
          <button
            onClick={() => setError(null)}
            className="text-xs text-error/70 hover:text-error underline mt-1"
          >
            Dismiss
          </button>
        </div>
      )}

      {/* Queue Items */}
      <div className="flex-1 overflow-y-auto p-4 space-y-3">
        {!isStreaming && items.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-8 text-center">
            <svg
              className="h-12 w-12 text-text-dim mb-3 opacity-50"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
              strokeWidth={1.5}
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                d="M15.75 5.25a3 3 0 013 3m3 0a6 6 0 01-7.029 5.912c-.563-.097-1.159.026-1.563.43L10.5 17.25H8.25v2.25H6v2.25H2.25v-2.818c0-.597.237-1.17.659-1.591l6.499-6.499c.404-.404.527-1 .43-1.563A6 6 0 1121.75 8.25z"
              />
            </svg>
            <p className="text-sm font-medium text-text-dim">
              Waiting for stream
            </p>
            <p className="text-xs text-text-dim mt-1">
              Start streaming in OBS to enable clip capture
            </p>
          </div>
        ) : isLoading ? (
          <div className="flex items-center justify-center py-8">
            <div className="text-sm text-text-muted">Loading...</div>
          </div>
        ) : filteredItems.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-8 text-center">
            <svg
              className="h-12 w-12 text-text-dim mb-3"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
              strokeWidth={1.5}
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"
              />
            </svg>
            <p className="text-sm text-text-dim">
              {filter === "all"
                ? "No clips in queue"
                : `No ${filter} clips`}
            </p>
            <p className="text-xs text-text-dim mt-1">
              Clips will appear here when triggered
            </p>
          </div>
        ) : (
          filteredItems.map((item) => (
            <ClipQueueItemCard
              key={item.id}
              item={item}
              onRetry={() => handleRetry(item.id)}
              onDelete={() => handleDelete(item.id)}
              onUpdateTitle={(title) => handleUpdateTitle(item.id, title)}
            />
          ))
        )}
      </div>

      {/* Footer Stats */}
      <div className="p-4 border-t border-stroke bg-surface">
        <div className="grid grid-cols-4 gap-2 text-center">
          <div>
            <p className="text-lg font-semibold text-text">{stats.pending}</p>
            <p className="text-xs text-text-dim">Pending</p>
          </div>
          <div>
            <p className="text-lg font-semibold text-warning">{stats.processing}</p>
            <p className="text-xs text-text-dim">Processing</p>
          </div>
          <div>
            <p className="text-lg font-semibold text-success">{stats.completed}</p>
            <p className="text-xs text-text-dim">Done</p>
          </div>
          <div>
            <p className="text-lg font-semibold text-error">{stats.failed}</p>
            <p className="text-xs text-text-dim">Failed</p>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Badge, Button } from "@/components/ui";

export interface ClipQueueItem {
  id: string;
  sessionId: string;
  status: "pending" | "recording" | "processing" | "completed" | "failed";
  triggerType: "audio" | "visual" | "manual";
  triggerSource?: string;
  triggerConfidence?: number;
  t0: number;
  t1?: number;
  clipId?: string;
  thumbnailPath?: string;
  title?: string;
  errorMessage?: string;
  createdAt: string;
}

interface ClipQueueItemCardProps {
  item: ClipQueueItem;
  onRetry?: () => void;
  onDelete?: () => void;
  onUpdateTitle?: (title: string) => void;
}

const STATUS_CONFIG = {
  pending: {
    label: "Pending",
    variant: "default" as const,
    icon: (
      <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
      </svg>
    ),
  },
  recording: {
    label: "Recording",
    variant: "error" as const,
    icon: (
      <span className="relative flex h-3 w-3">
        <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-error opacity-75" />
        <span className="relative inline-flex rounded-full h-3 w-3 bg-error" />
      </span>
    ),
  },
  processing: {
    label: "Processing",
    variant: "warning" as const,
    icon: (
      <svg className="h-3 w-3 animate-spin" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
      </svg>
    ),
  },
  completed: {
    label: "Completed",
    variant: "success" as const,
    icon: (
      <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
      </svg>
    ),
  },
  failed: {
    label: "Failed",
    variant: "error" as const,
    icon: (
      <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
      </svg>
    ),
  },
};

const TRIGGER_TYPE_CONFIG = {
  audio: {
    label: "Audio",
    icon: (
      <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
      </svg>
    ),
  },
  visual: {
    label: "Visual",
    icon: (
      <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
        <path strokeLinecap="round" strokeLinejoin="round" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
      </svg>
    ),
  },
  manual: {
    label: "Manual",
    icon: (
      <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M15 15l-2 5L9 9l11 4-5 2zm0 0l5 5M7.188 2.239l.777 2.897M5.136 7.965l-2.898-.777M13.95 4.05l-2.122 2.122m-5.657 5.656l-2.12 2.122" />
      </svg>
    ),
  },
};

export function ClipQueueItemCard({
  item,
  onRetry,
  onDelete,
  onUpdateTitle,
}: ClipQueueItemCardProps) {
  const [isEditing, setIsEditing] = useState(false);
  const [editTitle, setEditTitle] = useState(item.title || "");
  const [showActions, setShowActions] = useState(false);

  const statusConfig = STATUS_CONFIG[item.status];
  const triggerConfig = TRIGGER_TYPE_CONFIG[item.triggerType];

  const duration = item.t1 ? item.t1 - item.t0 : null;

  const handleSaveTitle = () => {
    if (onUpdateTitle && editTitle !== item.title) {
      onUpdateTitle(editTitle);
    }
    setIsEditing(false);
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, "0")}`;
  };

  return (
    <div
      className={`
        relative rounded-lg border transition-all
        ${item.status === "recording" ? "border-error bg-error/5" : "border-stroke bg-surface hover:bg-surface-hover"}
      `}
      onMouseEnter={() => setShowActions(true)}
      onMouseLeave={() => setShowActions(false)}
    >
      {/* Thumbnail */}
      <div className="relative aspect-video rounded-t-lg overflow-hidden bg-bg-0">
        {item.thumbnailPath ? (
          <img
            src={item.thumbnailPath}
            alt={item.title || "Clip thumbnail"}
            className="w-full h-full object-cover"
          />
        ) : (
          <div className="absolute inset-0 flex items-center justify-center">
            <svg
              className="h-8 w-8 text-text-dim"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
              strokeWidth={1.5}
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z"
              />
            </svg>
          </div>
        )}

        {/* Status Badge Overlay */}
        <div className="absolute top-2 left-2">
          <Badge variant={statusConfig.variant} className="text-xs flex items-center gap-1">
            {statusConfig.icon}
            {statusConfig.label}
          </Badge>
        </div>

        {/* Trigger Type Badge */}
        <div className="absolute top-2 right-2">
          <Badge variant="default" className="text-xs flex items-center gap-1 bg-black/50 border-none">
            {triggerConfig.icon}
            {triggerConfig.label}
          </Badge>
        </div>

        {/* Processing Progress */}
        {item.status === "processing" && (
          <div className="absolute bottom-0 left-0 right-0 h-1 bg-stroke">
            <div className="h-full bg-warning animate-pulse" style={{ width: "60%" }} />
          </div>
        )}

        {/* Recording Indicator */}
        {item.status === "recording" && (
          <div className="absolute bottom-2 right-2 flex items-center gap-1.5 px-2 py-1 rounded bg-error text-white text-xs">
            <span className="h-2 w-2 rounded-full bg-white animate-pulse" />
            REC
          </div>
        )}
      </div>

      {/* Content */}
      <div className="p-3">
        {/* Title */}
        {isEditing ? (
          <div className="flex items-center gap-2 mb-2">
            <input
              type="text"
              value={editTitle}
              onChange={(e) => setEditTitle(e.target.value)}
              className="flex-1 px-2 py-1 text-sm rounded border border-stroke bg-bg-0 text-text focus:border-teal focus:outline-none"
              autoFocus
              onKeyDown={(e) => {
                if (e.key === "Enter") handleSaveTitle();
                if (e.key === "Escape") setIsEditing(false);
              }}
            />
            <button
              onClick={handleSaveTitle}
              className="p-1 text-success hover:bg-success/10 rounded"
            >
              <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
              </svg>
            </button>
            <button
              onClick={() => setIsEditing(false)}
              className="p-1 text-text-dim hover:bg-stroke rounded"
            >
              <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>
        ) : (
          <h4
            className="text-sm font-medium text-text mb-1 truncate cursor-pointer hover:text-teal"
            onClick={() => setIsEditing(true)}
            title="Click to edit"
          >
            {item.title || item.triggerSource || "Untitled clip"}
          </h4>
        )}

        {/* Meta Info */}
        <div className="flex items-center gap-3 text-xs text-text-dim">
          <span>t0: {formatTime(item.t0)}</span>
          {item.t1 && <span>t1: {formatTime(item.t1)}</span>}
          {duration && <span>({duration.toFixed(0)}s)</span>}
        </div>

        {/* Trigger Source */}
        {item.triggerSource && item.triggerType === "audio" && (
          <p className="text-xs text-text-dim mt-1 italic">
            &quot;{item.triggerSource}&quot;
            {item.triggerConfidence && (
              <span className="ml-1">({(item.triggerConfidence * 100).toFixed(0)}%)</span>
            )}
          </p>
        )}

        {/* Error Message */}
        {item.status === "failed" && item.errorMessage && (
          <p className="text-xs text-error mt-2 p-2 bg-error/10 rounded">
            {item.errorMessage}
          </p>
        )}
      </div>

      {/* Actions Overlay */}
      {showActions && (item.status === "completed" || item.status === "failed") && (
        <div className="absolute inset-0 bg-black/60 rounded-lg flex items-center justify-center gap-2 transition-opacity">
          {item.status === "completed" && (
            <>
              <Button
                variant="ghost"
                size="sm"
                className="bg-white/20 hover:bg-white/30 text-white"
              >
                <svg className="h-4 w-4 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z" />
