            <h3 className="text-sm font-semibold text-text">Chapter Outline</h3>
            <p className="text-xs text-text-muted mt-0.5">
              {chapters.length} chapters / {totalWords.toLocaleString()} words
            </p>
          </div>
          <div className="flex items-center gap-2">
            {/* View toggle */}
            <div className="flex items-center rounded-lg bg-surface p-0.5">
              <button
                onClick={() => setViewMode("list")}
                className={cn(
                  "px-2 py-1 text-xs rounded-md transition-colors",
                  viewMode === "list"
                    ? "bg-bg-1 text-text"
                    : "text-text-muted hover:text-text"
                )}
              >
                List
              </button>
              <button
                onClick={() => setViewMode("grid")}
                className={cn(
                  "px-2 py-1 text-xs rounded-md transition-colors",
                  viewMode === "grid"
                    ? "bg-bg-1 text-text"
                    : "text-text-muted hover:text-text"
                )}
              >
                Grid
              </button>
            </div>
            <button
              onClick={() => onChapterAdd?.({
                number: chapters.length + 1,
                title: "",
                status: "outline",
                wordCount: 0,
                plotThreadIds: [],
                timelineEventIds: [],
              })}
              className={cn(
                "flex items-center gap-1.5 px-3 py-1.5 text-xs rounded-lg",
                "bg-teal/10 text-teal border border-teal/30",
                "hover:bg-teal/20 transition-colors"
              )}
            >
              <PlusIcon className="w-3.5 h-3.5" />
              Add Chapter
            </button>
          </div>
        </div>

        {/* Progress bar */}
        <div className="space-y-1">
          <div className="flex items-center justify-between text-[10px]">
            <span className="text-text-muted">Progress</span>
            <span className="text-teal font-medium">
              {completedCount}/{chapters.length} complete
            </span>
          </div>
          <div className="h-1.5 rounded-full bg-surface overflow-hidden">
            <div
              className="h-full bg-gradient-to-r from-teal to-teal/50 rounded-full transition-all duration-300"
              style={{ width: `${chapters.length > 0 ? (completedCount / chapters.length) * 100 : 0}%` }}
            />
          </div>
        </div>
      </div>

      {/* Chapters list */}
      <div className="flex-1 overflow-auto p-4">
        {chapters.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full">
            <DocumentIcon className="w-12 h-12 text-text-dim mb-3" />
            <p className="text-sm text-text-muted mb-1">No chapters yet</p>
            <p className="text-xs text-text-dim mb-4">Start building your manuscript</p>
            <button
              onClick={() => onChapterAdd?.({
                number: 1,
                title: "Chapter 1",
                status: "outline",
                wordCount: 0,
                plotThreadIds: [],
                timelineEventIds: [],
              })}
              className={cn(
                "flex items-center gap-1.5 px-4 py-2 text-sm rounded-lg",
                "bg-teal text-bg-0 font-medium",
                "hover:bg-teal/90 transition-colors"
              )}
            >
              <PlusIcon className="w-4 h-4" />
              Add First Chapter
            </button>
          </div>
        ) : (
          <div className={cn(
            viewMode === "grid"
              ? "grid grid-cols-2 gap-3"
              : "space-y-2"
          )}>
            {sortedChapters.map((chapter) => (
              <ChapterCard
                key={chapter.id}
                chapter={chapter}
                isExpanded={expandedChapters.has(chapter.id)}
                onToggle={() => toggleChapter(chapter.id)}
                onEdit={() => {
                  // Edit action
                }}
                onSummarize={() => onSummarizeChapter?.(chapter.id)}
              />
            ))}
          </div>
        )}
      </div>

      {/* Footer stats */}
      <div className="shrink-0 px-4 py-2 border-t border-stroke bg-bg-1">
        <div className="flex items-center justify-between text-[10px] text-text-dim">
          <div className="flex items-center gap-4">
            {Object.entries(
              chapters.reduce((acc, c) => {
                acc[c.status] = (acc[c.status] || 0) + 1;
                return acc;
              }, {} as Record<ChapterStatus, number>)
            ).map(([status, count]) => (
              <span key={status} className="flex items-center gap-1">
                <span className={cn("w-2 h-2 rounded-full", CHAPTER_STATUS_COLORS[status as ChapterStatus].bg)} />
                {count} {status}
              </span>
            ))}
          </div>
          <span>Avg: {chapters.length > 0 ? Math.round(totalWords / chapters.length).toLocaleString() : 0} words/chapter</span>
        </div>
      </div>
    </div>
  );
};

export { ChapterOutlinePanel };

"use client";

import { type FC, useState, useRef, useEffect } from "react";
import { cn } from "@/lib/utils";
import type { TranscriptLine, WriterNote } from "@/hooks/useWritersCorner";

// ============================================================================
// Writing Pad Component
// Live transcript display with writer notes sidebar
// ============================================================================

interface WritingPadProps {
  readonly transcriptLines: readonly TranscriptLine[];
  readonly writerNotes: readonly WriterNote[];
  readonly onAddNote: (text: string) => void;
  readonly onRemoveNote: (id: string) => void;
}

// Icons
const PencilSquareIcon: FC<{ className?: string }> = ({ className }) => (
  <svg className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5}>
    <path
      strokeLinecap="round"
      strokeLinejoin="round"
      d="M16.862 4.487l1.687-1.688a1.875 1.875 0 112.652 2.652L10.582 16.07a4.5 4.5 0 01-1.897 1.13L6 18l.8-2.685a4.5 4.5 0 011.13-1.897l8.932-8.931zm0 0L19.5 7.125M18 14v4.75A2.25 2.25 0 0115.75 21H5.25A2.25 2.25 0 013 18.75V8.25A2.25 2.25 0 015.25 6H10"
    />
  </svg>
);

const TrashIcon: FC<{ className?: string }> = ({ className }) => (
  <svg className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5}>
    <path
      strokeLinecap="round"
      strokeLinejoin="round"
      d="M14.74 9l-.346 9m-4.788 0L9.26 9m9.968-3.21c.342.052.682.107 1.022.166m-1.022-.165L18.16 19.673a2.25 2.25 0 01-2.244 2.077H8.084a2.25 2.25 0 01-2.244-2.077L4.772 5.79m14.456 0a48.108 48.108 0 00-3.478-.397m-12 .562c.34-.059.68-.114 1.022-.165m0 0a48.11 48.11 0 013.478-.397m7.5 0v-.916c0-1.18-.91-2.164-2.09-2.201a51.964 51.964 0 00-3.32 0c-1.18.037-2.09 1.022-2.09 2.201v.916m7.5 0a48.667 48.667 0 00-7.5 0"
    />
  </svg>
);

const MicrophoneIcon: FC<{ className?: string }> = ({ className }) => (
  <svg className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5}>
    <path
      strokeLinecap="round"
      strokeLinejoin="round"
      d="M12 18.75a6 6 0 006-6v-1.5m-6 7.5a6 6 0 01-6-6v-1.5m6 7.5v3.75m-3.75 0h7.5M12 15.75a3 3 0 01-3-3V4.5a3 3 0 116 0v8.25a3 3 0 01-3 3z"
    />
  </svg>
);

function formatTime(seconds: number): string {
  const m = Math.floor(seconds / 60);
  const s = Math.floor(seconds % 60);
  return `${m}:${s.toString().padStart(2, "0")}`;
}

// Speaker color mapping for consistent color assignments
const SPEAKER_COLORS = [
  "text-teal",
  "text-purple",
  "text-warning",
  "text-success",
  "text-error",
  "text-teal-400",
  "text-purple-400",
] as const;

function getSpeakerColor(speakerId: string, speakerIndex: Map<string, number>): string {
  if (!speakerIndex.has(speakerId)) {
    speakerIndex.set(speakerId, speakerIndex.size);
  }
  const index = speakerIndex.get(speakerId) ?? 0;
  return SPEAKER_COLORS[index % SPEAKER_COLORS.length];
}

const WritingPad: FC<WritingPadProps> = ({
  transcriptLines,
  writerNotes,
  onAddNote,
  onRemoveNote,
}) => {
  const [noteInput, setNoteInput] = useState("");
  const [isAutoScroll, setIsAutoScroll] = useState(true);
  const transcriptEndRef = useRef<HTMLDivElement>(null);
  const speakerIndexRef = useRef<Map<string, number>>(new Map());

  // Auto-scroll to bottom when new transcript lines arrive
  useEffect(() => {
    if (isAutoScroll && transcriptEndRef.current) {
      transcriptEndRef.current.scrollIntoView({ behavior: "smooth" });
    }
  }, [transcriptLines.length, isAutoScroll]);

  const handleAddNote = () => {
    if (noteInput.trim()) {
      onAddNote(noteInput);
      setNoteInput("");
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleAddNote();
    }
  };

  return (
    <div className="flex h-full flex-col">
      {/* Transcript area */}
      <div className="flex-1 overflow-hidden">
        <div className="flex h-full flex-col lg:flex-row gap-4">
          {/* Live Transcript */}
          <div className="flex-1 flex flex-col min-h-0">
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-2">
                <MicrophoneIcon className="h-4 w-4 text-teal" />
                <h4 className="text-sm font-medium text-text">Live Transcript</h4>
                {transcriptLines.length > 0 && (
                  <span className="text-xs text-text-dim">
                    {transcriptLines.length} lines
                  </span>
                )}
              </div>
              <button
                type="button"
                onClick={() => setIsAutoScroll((prev) => !prev)}
                className={cn(
                  "px-2 py-1 text-xs rounded-md transition-colors",
                  isAutoScroll
                    ? "bg-teal/10 text-teal border border-teal/30"
                    : "bg-surface text-text-muted"
                )}
                aria-label={isAutoScroll ? "Disable auto-scroll" : "Enable auto-scroll"}
              >
                {isAutoScroll ? "Auto-scroll on" : "Auto-scroll off"}
              </button>
            </div>

            <div className="flex-1 overflow-y-auto rounded-xl bg-bg-2 p-4 font-mono text-sm">
              {transcriptLines.length === 0 ? (
                <div className="flex h-full flex-col items-center justify-center">
                  <MicrophoneIcon className="h-10 w-10 text-text-dim mb-3" />
                  <p className="text-text-muted text-center">
                    Waiting for transcript...
                  </p>
                  <p className="text-xs text-text-dim text-center mt-1">
                    Speech will appear here in real-time
                  </p>
                </div>
              ) : (
                <div className="space-y-2">
                  {transcriptLines.map((line) => {
                    const speakerColor = getSpeakerColor(
                      line.speakerId ?? "unknown",
                      speakerIndexRef.current
                    );
                    return (
                      <div key={line.id} className="group flex gap-3">
                        <span className="shrink-0 text-xs text-text-dim tabular-nums pt-0.5">
                          {formatTime(line.t0)}
                        </span>
                        <div className="min-w-0">
                          <span className={cn("text-xs font-semibold uppercase", speakerColor)}>
                            {line.speakerId ?? "Unknown"}
                          </span>
                          <p className="text-text leading-relaxed">{line.text}</p>
                        </div>
                      </div>
                    );
                  })}
                  <div ref={transcriptEndRef} />
                </div>
              )}
            </div>
          </div>

          {/* Writer Notes */}
          <div className="w-full lg:w-72 flex flex-col min-h-0">
            <div className="flex items-center gap-2 mb-3">
              <PencilSquareIcon className="h-4 w-4 text-purple" />
              <h4 className="text-sm font-medium text-text">Writer Notes</h4>
              {writerNotes.length > 0 && (
                <span className="text-xs text-text-dim">{writerNotes.length}</span>
              )}
            </div>

            {/* Note input */}
            <div className="mb-3">
              <textarea
                value={noteInput}
                onChange={(e) => setNoteInput(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder="Add a note... (Enter to save)"
                rows={2}
                className={cn(
                  "w-full resize-none rounded-lg border bg-bg-2 px-3 py-2 text-sm text-text",
                  "border-stroke placeholder:text-text-dim",
                  "focus:outline-none focus:ring-2 focus:ring-purple/50 focus:border-purple"
                )}
              />
              <button
                type="button"
                onClick={handleAddNote}
                disabled={!noteInput.trim()}
                className={cn(
                  "mt-2 w-full rounded-lg px-3 py-1.5 text-xs font-medium transition-colors",
                  noteInput.trim()
                    ? "bg-purple/10 text-purple border border-purple/30 hover:bg-purple/20"
                    : "bg-surface text-text-dim cursor-not-allowed"
                )}
              >
                Add Note
              </button>
            </div>

            {/* Notes list */}
            <div className="flex-1 overflow-y-auto space-y-2">
              {writerNotes.length === 0 ? (
                <div className="flex flex-col items-center justify-center rounded-xl bg-bg-2 py-8">
                  <PencilSquareIcon className="h-8 w-8 text-text-dim mb-2" />
                  <p className="text-xs text-text-muted">No notes yet</p>
                </div>
              ) : (
                writerNotes.map((note) => (
                  <div
                    key={note.id}
                    className="group rounded-lg border border-stroke bg-bg-2 p-3"
                  >
                    <div className="flex items-start justify-between gap-2">
                      <p className="text-sm text-text leading-relaxed">{note.text}</p>
                      <button
                        type="button"
                        onClick={() => onRemoveNote(note.id)}
                        className="shrink-0 p-1 rounded text-text-dim opacity-0 group-hover:opacity-100 hover:text-error transition-all"
                        aria-label="Remove note"
                      >
                        <TrashIcon className="h-3.5 w-3.5" />
                      </button>
                    </div>
                    <p className="mt-1 text-[10px] text-text-dim">
                      {new Date(note.createdAt).toLocaleTimeString()}
                    </p>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export { WritingPad };

"use client";

import { type FC, useState, useMemo } from "react";
import { cn } from "@/lib/utils";
import type { NotesStackProps, Note, NoteCategory, NotePriority } from "./types";
import { CATEGORY_LABELS } from "./types";
import { NoteCard } from "./NoteCard";

// ============================================================================
// Notes Stack Component
// Collapsible notes panel organized by category
// ============================================================================

type FilterType = "all" | NoteCategory;
type SortType = "priority" | "date" | "category";

const NotesStack: FC<NotesStackProps> = ({
  notes,
  contributors,
  onNoteUpdate,
  onNoteAdd,
  onNoteResolve,
  onNoteDelete,
}) => {
  const [filter, setFilter] = useState<FilterType>("all");
  const [sort, setSort] = useState<SortType>("priority");
  const [showResolved, setShowResolved] = useState(false);
  const [expandedNotes, setExpandedNotes] = useState<Set<string>>(new Set());
  const [isAddingNote, setIsAddingNote] = useState(false);
  const [newNoteTitle, setNewNoteTitle] = useState("");
  const [newNoteCategory, setNewNoteCategory] = useState<NoteCategory>("general");

  const getContributor = (id: string) =>
    contributors.find((c) => c.id === id);

  const priorityOrder: Record<NotePriority, number> = {
    urgent: 0,
    high: 1,
    medium: 2,
    low: 3,
  };

  const filteredAndSortedNotes = useMemo(() => {
    let result = [...notes];

    // Filter by resolved status
    if (!showResolved) {
      result = result.filter((note) => !note.isResolved);
    }

    // Filter by category
    if (filter !== "all") {
      result = result.filter((note) => note.category === filter);
    }

    // Sort
    result.sort((a, b) => {
      switch (sort) {
        case "priority":
          return priorityOrder[a.priority] - priorityOrder[b.priority];
        case "date":
          return b.updatedAt.getTime() - a.updatedAt.getTime();
        case "category":
          return a.category.localeCompare(b.category);
        default:
          return 0;
      }
    });

    return result;
  }, [notes, filter, sort, showResolved]);

  const toggleNoteExpanded = (noteId: string) => {
    const newExpanded = new Set(expandedNotes);
    if (newExpanded.has(noteId)) {
      newExpanded.delete(noteId);
    } else {
      newExpanded.add(noteId);
    }
    setExpandedNotes(newExpanded);
  };

  const handleAddNote = () => {
    if (newNoteTitle.trim()) {
      onNoteAdd?.({
        title: newNoteTitle.trim(),
        content: "",
        category: newNoteCategory,
        priority: "medium",
        proposedBy: contributors[0]?.id || "unknown",
        isResolved: false,
      });
      setNewNoteTitle("");
      setNewNoteCategory("general");
      setIsAddingNote(false);
    }
  };

  const getCategoryCount = (category: NoteCategory | "all"): number => {
    if (category === "all") {
      return showResolved
        ? notes.length
        : notes.filter((n) => !n.isResolved).length;
    }
    return notes.filter(
      (n) => n.category === category && (showResolved || !n.isResolved)
    ).length;
  };

  const unresolvedCount = notes.filter((n) => !n.isResolved).length;
  const urgentCount = notes.filter(
    (n) => n.priority === "urgent" && !n.isResolved
  ).length;

  return (
    <div className="h-full flex flex-col bg-bg-0">
      {/* Header */}
      <div className="shrink-0 px-4 py-3 border-b border-stroke">
        <div className="flex items-center justify-between mb-3">
          <div className="flex items-center gap-2">
            <svg
              className="w-4 h-4 text-purple"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2"
              />
            </svg>
            <h3 className="text-sm font-semibold text-text">Notes Stack</h3>
          </div>
          <div className="flex items-center gap-2">
            {urgentCount > 0 && (
              <span className="px-2 py-0.5 text-xs rounded-full bg-error/10 text-error border border-error/30">
                {urgentCount} urgent
              </span>
            )}
            <span className="text-xs text-text-muted">
              {unresolvedCount} open
            </span>
          </div>
        </div>

        {/* Filters */}
        <div className="flex items-center gap-2 flex-wrap">
          {(
            ["all", "open-loop", "character", "attribution", "general"] as const
          ).map((cat) => (
            <button
              key={cat}
              onClick={() => setFilter(cat)}
              className={cn(
                "px-2 py-1 text-xs rounded-md transition-colors duration-150",
                filter === cat
                  ? "bg-teal/10 text-teal border border-teal/30"
                  : "bg-surface text-text-muted hover:text-text hover:bg-surface-hover"
              )}
            >
              {cat === "all" ? "All" : CATEGORY_LABELS[cat]} (
              {getCategoryCount(cat)})
            </button>
          ))}
        </div>
      </div>

      {/* Sort and options bar */}
      <div className="shrink-0 flex items-center justify-between px-4 py-2 border-b border-stroke-subtle bg-bg-1">
        <div className="flex items-center gap-2">
          <span className="text-xs text-text-dim">Sort:</span>
          <select
            value={sort}
            onChange={(e) => setSort(e.target.value as SortType)}
            className={cn(
              "px-2 py-1 text-xs rounded-md",
              "bg-surface border border-stroke text-text",
              "focus:outline-none focus:ring-2 focus:ring-teal/50"
            )}
          >
            <option value="priority">Priority</option>
            <option value="date">Date</option>
            <option value="category">Category</option>
          </select>
        </div>

        <div className="flex items-center gap-3">
          <label className="flex items-center gap-1.5 cursor-pointer">
            <input
              type="checkbox"
              checked={showResolved}
              onChange={(e) => setShowResolved(e.target.checked)}
              className={cn(
                "w-3.5 h-3.5 rounded border-stroke",
                "bg-surface text-teal",
                "focus:ring-2 focus:ring-teal/50 focus:ring-offset-0"
              )}
            />
            <span className="text-xs text-text-muted">Show resolved</span>
          </label>

          <button
            onClick={() => setIsAddingNote(true)}
            className={cn(
              "p-1.5 rounded-md",
              "text-text-muted hover:text-teal hover:bg-teal/10",
              "transition-colors duration-150"
            )}
            title="Add note"
          >
            <svg
              className="w-4 h-4"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M12 4v16m8-8H4"
              />
            </svg>
          </button>
        </div>
      </div>

      {/* Notes list */}
      <div className="flex-1 overflow-auto p-3 space-y-2">
        {/* Add note form */}
        {isAddingNote && (
          <div className="rounded-lg border border-stroke p-3 bg-bg-1">
            <input
              type="text"
              value={newNoteTitle}
              onChange={(e) => setNewNoteTitle(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") handleAddNote();
                if (e.key === "Escape") setIsAddingNote(false);
              }}
              placeholder="Note title..."
              className={cn(
                "w-full px-2 py-1.5 text-sm rounded-md mb-2",
                "bg-bg-2 border border-stroke text-text",
                "placeholder:text-text-dim",
                "focus:outline-none focus:ring-2 focus:ring-teal/50"
              )}
              autoFocus
            />
            <div className="flex items-center gap-2">
              <select
                value={newNoteCategory}
                onChange={(e) =>
                  setNewNoteCategory(e.target.value as NoteCategory)
                }
                className={cn(
                  "px-2 py-1 text-xs rounded-md",
                  "bg-bg-2 border border-stroke text-text",
                  "focus:outline-none focus:ring-2 focus:ring-teal/50"
                )}
              >
                <option value="general">General</option>
                <option value="open-loop">Open Loop</option>
                <option value="character">Character</option>
                <option value="attribution">Attribution</option>
              </select>
              <button
                onClick={handleAddNote}
                className={cn(
                  "px-3 py-1 text-xs font-medium rounded-md",
                  "bg-teal/10 text-teal border border-teal/30",
                  "hover:bg-teal/20 transition-colors"
                )}
              >
                Add
              </button>
              <button
                onClick={() => {
                  setIsAddingNote(false);
                  setNewNoteTitle("");
                }}
                className={cn(
                  "px-3 py-1 text-xs font-medium rounded-md",
                  "text-text-muted hover:text-text",
                  "transition-colors"
                )}
              >
                Cancel
              </button>
            </div>
          </div>
        )}

        {/* Notes */}
        {filteredAndSortedNotes.map((note) => (
          <NoteCard
            key={note.id}
            note={note}
            contributor={getContributor(note.proposedBy)}
            isExpanded={expandedNotes.has(note.id)}
            onToggleExpand={() => toggleNoteExpanded(note.id)}
            onResolve={onNoteResolve}
            onEdit={onNoteUpdate}
            onDelete={onNoteDelete}
          />
        ))}

        {/* Empty state */}
        {filteredAndSortedNotes.length === 0 && !isAddingNote && (
          <div className="py-8 text-center">
            <svg
              className="w-12 h-12 mx-auto text-text-dim mb-3"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={1}
                d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2"
              />
            </svg>
            <p className="text-sm text-text-muted mb-2">
              {filter === "all"
                ? "No notes yet"
                : `No ${CATEGORY_LABELS[filter as NoteCategory].toLowerCase()} notes`}
            </p>
            <button
