// ============================================================
// PlatformSelector Component
// ============================================================

export interface PlatformSelectorProps {
  selectedPlatforms: SocialPlatform[];
  onChange: (platforms: SocialPlatform[]) => void;
  maxSelection?: number;
  disabled?: boolean;
  showLabels?: boolean;
  size?: "sm" | "md" | "lg";
  layout?: "grid" | "horizontal";
}

export function PlatformSelector({
  selectedPlatforms,
  onChange,
  maxSelection,
  disabled = false,
  showLabels = true,
  size = "md",
  layout = "grid",
}: PlatformSelectorProps) {
  const handleToggle = (platform: SocialPlatform) => {
    if (disabled) return;

    if (selectedPlatforms.includes(platform)) {
      onChange(selectedPlatforms.filter((p) => p !== platform));
    } else {
      if (maxSelection && selectedPlatforms.length >= maxSelection) {
        return;
      }
      onChange([...selectedPlatforms, platform]);
    }
  };

  const handleSelectAll = () => {
    if (disabled) return;
    const allPlatforms = Object.keys(PLATFORM_CONFIGS) as SocialPlatform[];
    onChange(allPlatforms);
  };

  const handleDeselectAll = () => {
    if (disabled) return;
    onChange([]);
  };

  const sizeStyles = {
    sm: {
      button: "h-12 w-12",
      icon: "h-5 w-5",
      text: "text-xs",
      badge: "text-[10px] px-1.5 py-0.5",
    },
    md: {
      button: "h-16 w-16",
      icon: "h-6 w-6",
      text: "text-sm",
      badge: "text-xs px-2 py-0.5",
    },
    lg: {
      button: "h-20 w-20",
      icon: "h-8 w-8",
      text: "text-base",
      badge: "text-sm px-2.5 py-1",
    },
  };

  const styles = sizeStyles[size];

  return (
    <div className="space-y-4">
      {/* Header with Select All */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-sm font-semibold text-text">
            Select Platforms
            {maxSelection && (
              <span className="ml-2 text-xs text-text-muted">
                (Max {maxSelection})
              </span>
            )}
          </h3>
          <p className="mt-0.5 text-xs text-text-muted">
            {selectedPlatforms.length} selected
          </p>
        </div>
        <div className="flex gap-2">
          <button
            type="button"
            onClick={handleSelectAll}
            disabled={disabled}
            className="text-xs text-teal transition-colors hover:text-teal-400 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            Select All
          </button>
          <span className="text-xs text-text-dim">|</span>
          <button
            type="button"
            onClick={handleDeselectAll}
            disabled={disabled || selectedPlatforms.length === 0}
            className="text-xs text-text-muted transition-colors hover:text-text disabled:opacity-50 disabled:cursor-not-allowed"
          >
            Clear
          </button>
        </div>
      </div>

      {/* Platform Buttons */}
      <div
        className={cn(
          layout === "grid"
            ? "grid grid-cols-5 gap-3"
            : "flex flex-wrap gap-3",
          disabled && "opacity-60 pointer-events-none"
        )}
      >
        {(Object.entries(PLATFORM_CONFIGS) as [SocialPlatform, typeof PLATFORM_CONFIGS[SocialPlatform]][]).map(
          ([platformId, config]) => {
            const isSelected = selectedPlatforms.includes(platformId);
            const PlatformIcon = PLATFORM_ICONS[platformId];

            return (
              <div key={platformId} className="flex flex-col items-center gap-2">
                <button
                  type="button"
                  onClick={() => handleToggle(platformId)}
                  className={cn(
                    "relative flex items-center justify-center rounded-xl border-2 transition-all duration-200",
                    styles.button,
                    isSelected
                      ? "border-teal bg-teal/10 shadow-glow scale-105"
                      : "border-stroke bg-surface hover:bg-surface-hover hover:border-stroke-subtle"
                  )}
                  aria-label={`${isSelected ? "Deselect" : "Select"} ${config.name}`}
                  aria-pressed={isSelected}
                >
                  <PlatformIcon
                    className={styles.icon}
                    style={{
                      color: isSelected ? config.color : "currentColor",
                    }}
                  />

                  {/* Selection Indicator */}
                  {isSelected && (
                    <div className="absolute -right-1 -top-1 flex h-5 w-5 items-center justify-center rounded-full bg-teal">
                      <svg
                        className="h-3 w-3 text-bg-0"
                        viewBox="0 0 24 24"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="3"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                      >
                        <polyline points="20 6 9 17 4 12" />
                      </svg>
                    </div>
                  )}
                </button>

                {/* Platform Label */}
                {showLabels && (
                  <div className="flex flex-col items-center gap-0.5">
                    <span
                      className={cn(
                        "font-medium text-center",
                        styles.text,
                        isSelected ? "text-text" : "text-text-muted"
                      )}
                    >
                      {config.name}
                    </span>
                    <span
                      className={cn(
                        "rounded-full bg-bg-2 font-medium",
                        styles.badge,
                        isSelected ? "text-teal" : "text-text-dim"
                      )}
                    >
                      {config.characterLimit}
                    </span>
                  </div>
                )}
              </div>
            );
          }
        )}
      </div>
    </div>
  );
}

export default PlatformSelector;

