      return "bg-purple-500/20 text-purple-400";
    default:
      return "bg-gray-500/20 text-gray-400";
  }
}

export function ClipBin({
  clips,
  onPreview,
  onExport,
  onEditHook,
  isConnected,
}: ClipBinProps) {
