export function PostQueue({
  posts,
  onEdit,
  onApprove,
  onPublish,
  onCopy,
  onSchedule,
  onDelete,
  isConnected,
}: PostQueueProps) {
  const [selectedPlatform, setSelectedPlatform] = useState<Platform>("all");
  const [copiedId, setCopiedId] = useState<string | null>(null);

  const filteredPosts = useMemo(() => {
    if (selectedPlatform === "all") return posts;
    return posts.filter((post) => post.platform === selectedPlatform);
  }, [posts, selectedPlatform]);

  const platformCounts = useMemo(() => {
    const counts: Record<Platform, number> = {
      all: posts.length,
      x: 0,
      linkedin: 0,
      youtube: 0,
      instagram: 0,
      tiktok: 0,
    };
    posts.forEach((post) => {
      if (post.platform in counts) {
        counts[post.platform]++;
      }
    });
    return counts;
  }, [posts]);

  const handleCopy = async (post: SocialPost) => {
    await navigator.clipboard.writeText(post.text);
    setCopiedId(post.id);
    onCopy(post.text);
    setTimeout(() => setCopiedId(null), 2000);
  };

  return (
    <Card variant="elevated" className="h-full">
      <CardHeader>
        <div className="flex items-center justify-between">
          <div>
            <CardTitle className="flex items-center gap-2">
              Post Queue
              <Badge variant="teal">{posts.length}</Badge>
            </CardTitle>
            <CardDescription>
              AI-generated social posts ready for review
            </CardDescription>
          </div>
        </div>

        {/* Platform tabs */}
        <div className="mt-3 flex flex-wrap gap-1">
          {(Object.keys(PLATFORM_CONFIG) as Platform[]).map((platform) => {
            const config = PLATFORM_CONFIG[platform];
            const count = platformCounts[platform];
            const isActive = selectedPlatform === platform;

            return (
              <button
                key={platform}
                type="button"
                onClick={() => setSelectedPlatform(platform)}
                className={`flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-sm transition-colors ${
                  isActive
                    ? "bg-teal/20 text-teal"
                    : "bg-surface-elevated text-text-muted hover:bg-surface-hover"
                }`}
              >
                <span className={isActive ? "text-teal" : config.color}>
                  {config.icon}
                </span>
                <span>{config.label}</span>
                {count > 0 && (
                  <span
                    className={`ml-1 rounded-full px-1.5 text-xs ${
                      isActive ? "bg-teal/30" : "bg-surface"
                    }`}
                  >
                    {count}
                  </span>
                )}
              </button>
            );
          })}
        </div>
      </CardHeader>

      <CardContent>
        {!isConnected && (
          <div className="flex flex-col items-center justify-center py-12 text-center">
            <div className="animate-pulse text-text-muted">
              <svg className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M7.5 8.25h9m-9 3H12m-9.75 1.51c0 1.6 1.123 2.994 2.707 3.227 1.129.166 2.27.293 3.423.379.35.026.67.21.865.501L12 21l2.755-4.133a1.14 1.14 0 01.865-.501 48.172 48.172 0 003.423-.379c1.584-.233 2.707-1.626 2.707-3.228V6.741c0-1.602-1.123-2.995-2.707-3.228A48.394 48.394 0 0012 3c-2.392 0-4.744.175-7.043.513C3.373 3.746 2.25 5.14 2.25 6.741v6.018z" />
              </svg>
            </div>
            <p className="mt-3 text-sm text-text-muted">Connecting to live stream...</p>
          </div>
        )}

        {isConnected && filteredPosts.length === 0 && (
          <div className="flex flex-col items-center justify-center py-12 text-center">
            <svg className="h-8 w-8 text-text-muted" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M7.5 8.25h9m-9 3H12m-9.75 1.51c0 1.6 1.123 2.994 2.707 3.227 1.129.166 2.27.293 3.423.379.35.026.67.21.865.501L12 21l2.755-4.133a1.14 1.14 0 01.865-.501 48.172 48.172 0 003.423-.379c1.584-.233 2.707-1.626 2.707-3.228V6.741c0-1.602-1.123-2.995-2.707-3.228A48.394 48.394 0 0012 3c-2.392 0-4.744.175-7.043.513C3.373 3.746 2.25 5.14 2.25 6.741v6.018z" />
            </svg>
            <p className="mt-3 text-sm text-text-muted">
              {selectedPlatform === "all"
                ? "No posts generated yet"
                : `No ${PLATFORM_CONFIG[selectedPlatform].label} posts yet`}
            </p>
            <p className="mt-1 text-xs text-text-muted">
              Posts will appear here as AI generates them
            </p>
          </div>
        )}

        {isConnected && filteredPosts.length > 0 && (
          <div className="space-y-3">
            {filteredPosts.map((post) => {
              const platformConfig = PLATFORM_CONFIG[post.platform] || PLATFORM_CONFIG.all;
              const statusConfig = STATUS_CONFIG[post.status];

              return (
                <div
                  key={post.id}
                  className="group rounded-xl border border-stroke bg-surface p-4 transition-all hover:border-teal/30"
                >
                  {/* Header */}
                  <div className="mb-2 flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <span className={platformConfig.color}>{platformConfig.icon}</span>
                      <span className="text-xs font-medium text-text-muted">
                        {platformConfig.label}
                      </span>
                    </div>
                    <div className="flex items-center gap-2">
                      <span className={`rounded px-2 py-0.5 text-xs ${statusConfig.color}`}>
                        {statusConfig.label}
                      </span>
                      <span className="text-xs text-text-muted">{post.timestamp}</span>
                    </div>
                  </div>

                  {/* Content */}
                  <p className="mb-3 whitespace-pre-wrap text-sm text-text">{post.text}</p>

                  {/* Actions */}
                  <div className="flex flex-wrap items-center gap-2">
                    <Button
                      variant="ghost"
                      size="sm"
                      className="h-7 gap-1 text-xs"
                      onClick={() => handleCopy(post)}
                    >
                      {copiedId === post.id ? (
                        <>
                          <CheckIcon />
                          Copied!
                        </>
                      ) : (
                        <>
                          <CopyIcon />
                          Copy
                        </>
                      )}
                    </Button>

                    <Button
                      variant="ghost"
                      size="sm"
                      className="h-7 gap-1 text-xs"
                      onClick={() => onEdit(post)}
                    >
                      <EditIcon />
                      Edit
                    </Button>

                    {post.status === "draft" && (
                      <Button
                        variant="ghost"
                        size="sm"
                        className="h-7 gap-1 text-xs text-green-400 hover:text-green-300"
                        onClick={() => onApprove(post.id)}
                      >
                        <CheckIcon />
                        Approve
                      </Button>
                    )}

                    {(post.status === "approved" || post.status === "draft") && (
                      <Button
                        variant="ghost"
                        size="sm"
                        className="h-7 gap-1 text-xs text-teal hover:text-teal-400"
                        onClick={() => onPublish(post.id)}
                      >
                        <SendIcon />
                        Publish
                      </Button>
                    )}

                    <Button
                      variant="ghost"
                      size="sm"
                      className="ml-auto h-7 gap-1 text-xs text-red-400 opacity-0 transition-opacity group-hover:opacity-100 hover:text-red-300"
                      onClick={() => onDelete(post.id)}
                    >
                      <TrashIcon />
                    </Button>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

export default PostQueue;

