// ============================================================
// Live Video Preview Component
// ============================================================

export function LiveVideoPreview({
  webrtcUrl = "http://localhost:8889/live/stream",
  hlsUrl = "http://localhost:8888/live/stream/index.m3u8",
  className,
  onConnectionChange,
  onError,
  isStreamActive = false,
  sessionId = null,
  enabledGestures = [],
  gestureDetectionEnabled = false,
  onGestureTrigger,
}: LiveVideoPreviewProps) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const hlsRef = useRef<HlsType | null>(null);
  const peerConnectionRef = useRef<RTCPeerConnection | null>(null);
  const reconnectTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const trackReceivedRef = useRef(false);

  const [connectionState, setConnectionState] =
    useState<ConnectionState>("disconnected");
  const [streamMode, setStreamMode] = useState<StreamMode>("none");
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [latencyMs, setLatencyMs] = useState<number | null>(null);
  const [reconnectAttempts, setReconnectAttempts] = useState(0);
  const preferHlsUntilRef = useRef<number>(0);
  const lastActiveAtRef = useRef<number>(0);

  const MAX_RECONNECT_ATTEMPTS = 3;
  const WEBRTC_BACKOFF_MS = 30000;

  /**
   * Update connection state and notify parent
   */
  const updateConnectionState = useCallback(
    (state: ConnectionState) => {
      setConnectionState(state);
      onConnectionChange?.(state === "connected");
    },
    [onConnectionChange]
  );

  /**
   * Handle errors
   */
  const handleError = useCallback(
    (error: Error, message?: string) => {
      setErrorMessage(message ?? error.message);
      updateConnectionState("error");
      onError?.(error);
    },
    [onError, updateConnectionState]
  );

  /**
   * Clean up WebRTC connection
   */
  const cleanupWebRTC = useCallback(() => {
    if (peerConnectionRef.current) {
      peerConnectionRef.current.close();
      peerConnectionRef.current = null;
    }
    trackReceivedRef.current = false;
  }, []);

  /**
   * Clean up HLS instance
   */
  const cleanupHLS = useCallback(() => {
    if (hlsRef.current) {
      hlsRef.current.destroy();
      hlsRef.current = null;
    }
  }, []);

  /**
   * Clean up all connections
   */
  const cleanup = useCallback(() => {
    cleanupWebRTC();
    cleanupHLS();

    if (reconnectTimeoutRef.current) {
      clearTimeout(reconnectTimeoutRef.current);
      reconnectTimeoutRef.current = null;
    }

    if (videoRef.current) {
      videoRef.current.srcObject = null;
      videoRef.current.src = "";
    }
  }, [cleanupWebRTC, cleanupHLS]);

  /**
   * Connect via WebRTC for lowest latency
   */
  const connectWebRTC = useCallback(async (): Promise<boolean> => {
    if (!videoRef.current) return false;
    if (typeof RTCPeerConnection === "undefined") return false;

    const toHttpUrl = (url: string) =>
      url.replace(/^ws:\/\//i, "http://").replace(/^wss:\/\//i, "https://");
    const normalizeUrl = (url: string) => url.replace(/\/+$/, "");
    const ensureWhep = (url: string) =>
      url.endsWith("/whep") ? url : `${url}/whep`;

    try {
      updateConnectionState("connecting");
      setStreamMode("webrtc");

      // Create peer connection
      const pc = new RTCPeerConnection({
        iceServers: [{ urls: "stun:stun.l.google.com:19302" }],
      });
      peerConnectionRef.current = pc;

      // Add transceiver for receiving video
      pc.addTransceiver("video", { direction: "recvonly" });
      pc.addTransceiver("audio", { direction: "recvonly" });

      const mediaReady = new Promise<boolean>((resolve) => {
        const timeout = setTimeout(() => resolve(false), 5000);
        const onLoadedMetadata = () => {
          clearTimeout(timeout);
          resolve(true);
        };

        pc.ontrack = (event) => {
          if (videoRef.current && event.streams[0]) {
            trackReceivedRef.current = true;
            videoRef.current.srcObject = event.streams[0];
            videoRef.current.addEventListener("loadedmetadata", onLoadedMetadata, {
              once: true,
            });
            videoRef.current.play().catch(() => {
              // Autoplay may be blocked
            });
          }
        };
      });

      // Create offer
      const offer = await pc.createOffer();
      await pc.setLocalDescription(offer);

      // Wait for ICE gathering to complete
      await new Promise<void>((resolve) => {
        if (pc.iceGatheringState === "complete") {
          resolve();
        } else {
          const checkState = () => {
            if (pc.iceGatheringState === "complete") {
              pc.removeEventListener("icegatheringstatechange", checkState);
              resolve();
            }
          };
          pc.addEventListener("icegatheringstatechange", checkState);
        }
      });

      // Send offer to WHEP endpoint (MediaMTX expects /whep)
      const baseUrl = normalizeUrl(toHttpUrl(webrtcUrl));
      const candidates = baseUrl.endsWith("/whep")
        ? [baseUrl]
        : [ensureWhep(baseUrl), baseUrl];

      let answerSdp: string | null = null;
      let lastError: Error | null = null;

      for (const url of candidates) {
        try {
          const response = await fetch(url, {
            method: "POST",
            headers: {
              "Content-Type": "application/sdp",
            },
            body: pc.localDescription?.sdp,
          });

          if (!response.ok) {
            throw new Error(`WebRTC signaling failed: ${response.statusText}`);
          }

          answerSdp = await response.text();
          break;
        } catch (err) {
          lastError = err instanceof Error ? err : new Error("WebRTC signaling failed");
        }
      }

      if (!answerSdp) {
        throw lastError ?? new Error("WebRTC signaling failed");
      }

      await pc.setRemoteDescription({
        type: "answer",
        sdp: answerSdp,
      });

      // Monitor connection state and wait for a stable connection
      const connected = await new Promise<boolean>((resolve) => {
        const timeout = setTimeout(() => resolve(false), 5000);
        const handler = () => {
          switch (pc.connectionState) {
            case "connected":
              clearTimeout(timeout);
              pc.removeEventListener("connectionstatechange", handler);
              resolve(true);
              break;
            case "disconnected":
            case "failed":
            case "closed":
              clearTimeout(timeout);
              pc.removeEventListener("connectionstatechange", handler);
              resolve(false);
              break;
          }
        };
        pc.addEventListener("connectionstatechange", handler);
      });

      if (!connected) {
        throw new Error("WebRTC connection failed");
      }

      const hasMedia = await mediaReady;
      if (!hasMedia) {
        throw new Error("WebRTC connected but no media received");
      }

      updateConnectionState("connected");
      setLatencyMs(100); // WebRTC typically <500ms latency
      setReconnectAttempts(0);
      return true;
    } catch (error) {
      cleanupWebRTC();
      return false;
    }
  }, [webrtcUrl, updateConnectionState, cleanupWebRTC]);

  /**
   * Connect via HLS as fallback
   */
  const connectHLS = useCallback(async (): Promise<boolean> => {
    if (!videoRef.current) return false;

    try {
      updateConnectionState("connecting");
      setStreamMode("hls");

      // Confirm HLS playlist is reachable before attaching
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 2000);
      let hlsReady = false;

      try {
        const response = await fetch(hlsUrl, {
          method: "GET",
          cache: "no-store",
          signal: controller.signal,
        });
        hlsReady = response.ok;
      } catch {
        hlsReady = false;
      } finally {
        clearTimeout(timeout);
      }

      if (!hlsReady) {
        cleanupHLS();
        return false;
      }

      // Check if HLS is supported natively (Safari)
      if (videoRef.current.canPlayType("application/vnd.apple.mpegurl")) {
        videoRef.current.src = hlsUrl;
        videoRef.current.addEventListener(
          "loadedmetadata",
          () => {
            updateConnectionState("connected");
            setLatencyMs(2000); // HLS typically 2-5s latency
            setReconnectAttempts(0);
            videoRef.current?.play().catch(() => {});
          },
          { once: true }
        );
        videoRef.current.addEventListener(
          "error",
          () => {
            updateConnectionState("error");
            setErrorMessage("Failed to load HLS stream");
          },
          { once: true }
        );
        return true;
      }

      // Use hls.js for other browsers - dynamic import to avoid SSR issues
      try {
        const HlsModule = await import("hls.js");
        const Hls = HlsModule.default;

        if (!Hls.isSupported()) {
          throw new Error("HLS is not supported in this browser");
        }

        const hls = new Hls({
          lowLatencyMode: true,
          liveSyncDurationCount: 3,
          liveMaxLatencyDurationCount: 10,
          enableWorker: true,
        });
        hlsRef.current = hls;

        hls.loadSource(hlsUrl);
        hls.attachMedia(videoRef.current);

        hls.on(Hls.Events.MANIFEST_PARSED, () => {
          updateConnectionState("connected");
          setLatencyMs(2000);
          setReconnectAttempts(0);
          videoRef.current?.play().catch(() => {});
        });

        hls.on(Hls.Events.ERROR, (_, data) => {
          if (data.fatal) {
            switch (data.type) {
              case Hls.ErrorTypes.NETWORK_ERROR:
                // Try to recover
                hls.startLoad();
                break;
              case Hls.ErrorTypes.MEDIA_ERROR:
                hls.recoverMediaError();
                break;
              default:
                handleError(
                  new Error("HLS fatal error"),
                  "Failed to play HLS stream"
                );
                break;
            }
          }
        });

        return true;
      } catch (importError) {
        // HLS.js not available, fall back to error state
        throw new Error("HLS library not available");
      }
    } catch (error) {
      cleanupHLS();
      return false;
    }
  }, [hlsUrl, updateConnectionState, cleanupHLS, handleError]);

  /**
   * Attempt to connect, trying WebRTC first, then falling back to HLS
   */
  const connect = useCallback(async () => {
    cleanup();
    setErrorMessage(null);

    const now = Date.now();
    if (isStreamActive) {
      lastActiveAtRef.current = now;
    }

    // Only attempt connection if stream is expected to be active
    if (!isStreamActive && now - lastActiveAtRef.current > 5000) {
      updateConnectionState("disconnected");
      setStreamMode("none");
      return;
    }

    const shouldSkipWebRTC = now < preferHlsUntilRef.current;
    if (!shouldSkipWebRTC) {
      // Try WebRTC first for lowest latency
      const webrtcSuccess = await connectWebRTC();
      if (webrtcSuccess) {
        return;
      }
      // Back off WebRTC for a bit if it failed
      preferHlsUntilRef.current = Date.now() + WEBRTC_BACKOFF_MS;
    }

    // Fall back to HLS
    const hlsSuccess = await connectHLS();
    if (hlsSuccess) {
      return;
    }

    // Both failed
    handleError(
      new Error("Unable to connect to stream"),
      "Could not establish connection to the video stream"
    );
  }, [
    cleanup,
    isStreamActive,
    updateConnectionState,
    connectWebRTC,
    connectHLS,
    handleError,
  ]);

  /**
   * Retry connection
   */
  const retry = useCallback(() => {
    if (reconnectAttempts < MAX_RECONNECT_ATTEMPTS) {
      setReconnectAttempts((prev) => prev + 1);
      connect();
    } else {
      handleError(
        new Error("Max reconnect attempts reached"),
        "Unable to connect after multiple attempts. Please check your stream settings."
      );
    }
  }, [reconnectAttempts, connect, handleError]);

  /**
   * Effect to handle connection when stream becomes active
   */
  useEffect(() => {
    const now = Date.now();
    if (isStreamActive) {
      if (connectionState !== "connected") {
        connect();
      }
    } else if (now - lastActiveAtRef.current > 5000) {
      cleanup();
      updateConnectionState("disconnected");
      setStreamMode("none");
    }
  }, [isStreamActive, connect, cleanup, updateConnectionState, connectionState]);

  useEffect(() => {
    return () => {
      cleanup();
    };
  }, [cleanup]);

  /**
   * Render content based on connection state
   */
  const renderContent = () => {
    switch (connectionState) {
      case "connecting":
        return (
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="text-center">
              <div className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-surface">
                <div className="h-8 w-8 animate-spin rounded-full border-2 border-teal border-t-transparent" />
              </div>
              <p className="text-sm text-text-muted">Connecting to stream...</p>
              <p className="mt-1 text-xs text-text-dim">
                {streamMode === "webrtc"
                  ? "Attempting WebRTC connection"
                  : "Attempting HLS connection"}
              </p>
            </div>
          </div>
        );

      case "disconnected":
        return (
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="text-center">
              <div className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-surface">
                {isStreamActive ? (
                  <WifiOffIcon className="h-6 w-6 text-text-muted" />
                ) : (
                  <PlayIcon className="h-6 w-6 text-text-muted" />
                )}
              </div>
              <p className="text-sm text-text-muted">
                {isStreamActive
                  ? "Stream disconnected"
                  : "Waiting for stream connection..."}
              </p>
              <p className="mt-1 text-xs text-text-dim">
                {isStreamActive
                  ? "The stream connection was lost"
                  : "Video preview will appear when OBS is streaming"}
              </p>
              {isStreamActive && (
                <button
                  type="button"
                  onClick={retry}
                  className="mt-4 inline-flex items-center gap-2 rounded-lg bg-surface px-4 py-2 text-sm font-medium text-teal transition-colors hover:bg-surface-hover"
                >
                  <RefreshIcon className="h-4 w-4" />
                  Reconnect
                </button>
              )}
            </div>
          </div>
        );

      case "error":
        return (
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="text-center">
              <div className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-error/10">
                <ExclamationIcon className="h-6 w-6 text-error" />
              </div>
              <p className="text-sm text-error">Connection Error</p>
              <p className="mt-1 max-w-xs text-xs text-text-dim">
                {errorMessage ?? "An unknown error occurred"}
              </p>
              <button
                type="button"
                onClick={retry}
                disabled={reconnectAttempts >= MAX_RECONNECT_ATTEMPTS}
                className="mt-4 inline-flex items-center gap-2 rounded-lg bg-surface px-4 py-2 text-sm font-medium text-teal transition-colors hover:bg-surface-hover disabled:cursor-not-allowed disabled:opacity-50"
              >
                <RefreshIcon className="h-4 w-4" />
                {reconnectAttempts >= MAX_RECONNECT_ATTEMPTS
                  ? "Max retries reached"
                  : "Retry Connection"}
              </button>
            </div>
          </div>
        );

      case "connected":
        return null; // Video element handles display
    }
  };

  return (
    <div
      className={cn(
        "relative aspect-video w-full overflow-hidden rounded-xl bg-bg-2",
        className
      )}
    >
      {/* Video Element */}
      <video
        ref={videoRef}
        className={cn(
          "h-full w-full object-contain",
          connectionState !== "connected" && "hidden"
        )}
        autoPlay
        playsInline
        muted
        controls={false}
      />

      {/* Gesture Detection Overlay */}
      {connectionState === "connected" && gestureDetectionEnabled && (
        <GestureDetectionOverlay
          sessionId={sessionId}
          videoRef={videoRef}
          enabledGestures={enabledGestures}
          enabled={gestureDetectionEnabled}
          onGestureTrigger={onGestureTrigger}
        />
      )}

      {/* State-based Content */}
      {renderContent()}

      {/* LIVE Badge */}
      <div className="absolute left-4 top-4">
        <div
          className={cn(
            "inline-flex items-center gap-1.5 rounded-full border px-3 py-1.5 text-xs font-medium",
            connectionState === "connected"
              ? "border-transparent bg-red-600 text-white"
              : "border-stroke bg-surface text-text-muted opacity-50"
          )}
        >
          <span className="relative flex h-2 w-2">
            {connectionState === "connected" && (
              <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-white opacity-75" />
            )}
            <span
              className={cn(
                "relative inline-flex h-2 w-2 rounded-full",
                connectionState === "connected" ? "bg-white" : "bg-text-muted"
              )}
            />
          </span>
          {connectionState === "connected" ? "LIVE" : "OFFLINE"}
        </div>
      </div>

      {/* Latency Indicator */}
      {connectionState === "connected" && latencyMs !== null && (
        <div className="absolute right-4 top-4">
          <div
            className={cn(
              "inline-flex items-center gap-1.5 rounded-full border border-stroke/50 bg-bg-0/80 px-2.5 py-1 text-xs font-medium backdrop-blur-sm",
              streamMode === "webrtc" ? "text-teal" : "text-warning"
            )}
          >
            <span
              className={cn(
                "h-1.5 w-1.5 rounded-full",
                streamMode === "webrtc" ? "bg-teal" : "bg-warning"
              )}
            />
            {streamMode === "webrtc" ? "WebRTC" : "HLS"} ~{latencyMs}ms
          </div>
        </div>
      )}
    </div>
  );
}

