/**
 * Custom hook for managing Court Session state with real-time WebSocket updates.
 *
 * Listens for OUTPUT_CREATED events with categories:
 * - CLAIM: Legal claims, allegations, and rebuttals
 * - EVIDENCE_CARD: Evidence items with exhibit references
 * - QUOTE: Witness testimony key points
 * - MODERATOR_PROMPT: Judicial or moderator interventions
 *
 * Derives:
 * - Evidence board items
 * - Legal claims and argument timeline
 * - Objections
 * - Verdict progress tracking
 * - Participant tracking
 */

import { useState, useEffect, useMemo, useCallback } from "react";
import { useWebSocket } from "@/contexts/WebSocketContext";
import type { EventEnvelope } from "@livestream-copilot/shared";
import type {
  LegalEvidence,
  LegalClaim,
  Objection,
  VerdictProgress,
  TimelineEvent,
  TrialPhase,
  LegalParty,
  EvidenceType,
  EvidenceStatus,
  ObjectionType,
  ObjectionRuling,
} from "@/components/dashboards/court/types";
import type { Participant } from "@/components/dashboards/court/CaseOverviewPanel";

// =============================================================================
// Types
// =============================================================================

interface OutputPayload {
  outputId: string;
  category: string;
  title?: string;
  text: string;
  refs: string[];
  meta: Record<string, unknown>;
}

export interface UseCourtSessionReturn {
  // Core data
  evidence: LegalEvidence[];
  claims: LegalClaim[];
  objections: Objection[];
  timeline: TimelineEvent[];
  participants: Participant[];
  verdictProgress: VerdictProgress;

  // Derived stats
  evidenceCount: number;
  claimCount: number;
  objectionCount: number;
  prosecutionClaimCount: number;
  defenseClaimCount: number;

  // Connection state
  isConnected: boolean;

  // Selections
  selectedEvidenceId: string | null;
  selectEvidence: (id: string | null) => void;
}

// =============================================================================
// Helper Functions
// =============================================================================

function generateId(): string {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

function formatTimestamp(ts: number): string {
  const date = new Date(ts);
  return date.toLocaleTimeString(undefined, {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
}

function extractParty(meta: Record<string, unknown>): LegalParty {
  const party = meta.party as string | undefined;
  if (party === "prosecution" || party === "defense" || party === "court") {
    return party;
  }
  const speaker = meta.speaker as string | undefined;
  if (speaker?.toLowerCase().includes("prosecut")) return "prosecution";
  if (speaker?.toLowerCase().includes("defen")) return "defense";
  if (speaker?.toLowerCase().includes("judge") || speaker?.toLowerCase().includes("court")) return "court";
  return "neutral";
}

function extractEvidenceType(meta: Record<string, unknown>): EvidenceType {
  const type = meta.evidenceType as string | undefined;
  if (type && ["document", "photo", "video", "audio", "physical", "testimony", "digital"].includes(type)) {
    return type as EvidenceType;
  }
  return "document";
}

function extractEvidenceStatus(meta: Record<string, unknown>): EvidenceStatus {
  const status = meta.status as string | undefined;
  if (status && ["admitted", "objected", "pending", "withdrawn"].includes(status)) {
    return status as EvidenceStatus;
  }
  return "pending";
}

function extractObjectionType(meta: Record<string, unknown>): ObjectionType {
  const type = meta.objectionType as string | undefined;
  if (type && [
    "hearsay", "relevance", "leading", "speculation", "argumentative",
    "compound", "asked_and_answered", "assumes_facts", "character", "foundation"
  ].includes(type)) {
    return type as ObjectionType;
  }
  return "other";
}

function extractObjectionRuling(meta: Record<string, unknown>): ObjectionRuling {
  const ruling = meta.ruling as string | undefined;
  if (ruling === "sustained" || ruling === "overruled") return ruling;
  return "pending";
}

function extractClaimStrength(meta: Record<string, unknown>): number {
  const strength = meta.strength as number | undefined;
  if (typeof strength === "number" && strength >= 0 && strength <= 100) return strength;
  return 50;
}

function isObjectionClaim(text: string, meta: Record<string, unknown>): boolean {
  const isObjection = meta.isObjection as boolean | undefined;
  if (isObjection === true) return true;
  return text.toLowerCase().startsWith("objection");
}

// =============================================================================
// Hook
// =============================================================================

export function useCourtSession(sessionId: string): UseCourtSessionReturn {
  const { events, isConnected } = useWebSocket();

  const [evidence, setEvidence] = useState<LegalEvidence[]>([]);
  const [claims, setClaims] = useState<LegalClaim[]>([]);
  const [objections, setObjections] = useState<Objection[]>([]);
  const [timeline, setTimeline] = useState<TimelineEvent[]>([]);
  const [participantMap, setParticipantMap] = useState<Map<string, Participant>>(new Map());
  const [selectedEvidenceId, setSelectedEvidenceId] = useState<string | null>(null);
  const [processedEventIds] = useState<Set<string>>(new Set());

  // Process incoming WebSocket events
  useEffect(() => {
    const newEvents = events.filter(
      (e) =>
        (e.type === "OUTPUT_CREATED" || e.type === "OUTPUT_VALIDATED") &&
        !processedEventIds.has(e.id) &&
        (!e.sessionId || e.sessionId === sessionId)
    );

    if (newEvents.length === 0) return;

    newEvents.forEach((event) => {
      processedEventIds.add(event.id);

      if (event.type !== "OUTPUT_CREATED") return;

      const payload = event.payload as OutputPayload;
      const { category, text, meta, outputId } = payload;
      const title = payload.title ?? "";
      const ts = event.ts;
      const timestamp = formatTimestamp(ts);
      const party = extractParty(meta);

      // Track participants
      const speakerName = (meta.speaker as string) || (meta.speakerId as string);
      if (speakerName) {
        setParticipantMap((prev) => {
          if (prev.has(speakerName)) return prev;
          const role =
            party === "prosecution" ? "prosecution" as const :
            party === "defense" ? "defense" as const :
            party === "court" ? "judge" as const :
            "witness" as const;
          const newMap = new Map(prev);
          newMap.set(speakerName, {
            id: speakerName,
            name: speakerName,
            role,
            party,
            isActive: true,
          });
          return newMap;
        });
      }

      switch (category) {
        case "CLAIM": {
          if (isObjectionClaim(text, meta)) {
            // Route to objections
            const objection: Objection = {
              id: outputId || generateId(),
              type: extractObjectionType(meta),
              party,
              timestamp,
              sessionTimestamp: ts,
              context: text,
              ruling: extractObjectionRuling(meta),
              rulingReason: (meta.rulingReason as string) || undefined,
              witnessId: (meta.witnessId as string) || undefined,
              isAiGenerated: true,
            };
            setObjections((prev) => [...prev, objection]);

            // Add to timeline
            setTimeline((prev) => [...prev, {
              id: generateId(),
              type: "objection",
              title: `Objection: ${OBJECTION_TYPE_LABELS_SHORT[objection.type] || objection.type}`,
              description: text,
              timestamp,
              sessionTimestamp: ts,
              party,
              linkedIds: [objection.id],
              isKeyMoment: true,
              isAiGenerated: true,
            }]);
          } else {
            // Standard claim
            const claim: LegalClaim = {
              id: outputId || generateId(),
              text,
              party,
              timestamp,
              sessionTimestamp: ts,
              type: extractClaimType(meta),
              evidenceIds: (meta.evidenceIds as string[]) || [],
              witnessIds: (meta.witnessIds as string[]) || [],
              strength: extractClaimStrength(meta),
              isContested: (meta.isContested as boolean) || false,
              isAiGenerated: true,
            };
            setClaims((prev) => [...prev, claim]);

            setTimeline((prev) => [...prev, {
              id: generateId(),
              type: "evidence",
              title: title || `${party} claim`,
              description: text.length > 120 ? `${text.slice(0, 117)}...` : text,
              timestamp,
              sessionTimestamp: ts,
              party,
              linkedIds: [claim.id],
              isKeyMoment: claim.strength >= 70,
              isAiGenerated: true,
            }]);
          }
          break;
        }

        case "EVIDENCE_CARD": {
          const evidenceItem: LegalEvidence = {
            id: outputId || generateId(),
            label: title || `Exhibit ${evidence.length + 1}`,
            type: extractEvidenceType(meta),
            description: text,
            timestamp,
            sessionTimestamp: ts,
            status: extractEvidenceStatus(meta),
            submittedBy: party,
            linkedWitnessIds: (meta.witnessIds as string[]) || [],
            linkedClaimIds: (meta.claimIds as string[]) || [],
            linkedEvidenceIds: (meta.linkedEvidenceIds as string[]) || [],
            tags: (meta.tags as string[]) || [],
            notes: (meta.notes as string) || undefined,
            source: (meta.source as string) || undefined,
            isAiGenerated: true,
          };
          setEvidence((prev) => [...prev, evidenceItem]);

          setTimeline((prev) => [...prev, {
            id: generateId(),
            type: "evidence",
            title: `Evidence: ${evidenceItem.label}`,
            description: text.length > 120 ? `${text.slice(0, 117)}...` : text,
            timestamp,
            sessionTimestamp: ts,
            party,
            linkedIds: [evidenceItem.id],
            isKeyMoment: false,
            isAiGenerated: true,
          }]);
          break;
        }

        case "QUOTE": {
          // Treat quotes as testimony-based claims
          const claim: LegalClaim = {
            id: outputId || generateId(),
            text: title ? `"${text}" - ${title}` : `"${text}"`,
            party,
            timestamp,
            sessionTimestamp: ts,
            type: "claim",
            evidenceIds: [],
            witnessIds: (meta.witnessIds as string[]) || [],
            strength: extractClaimStrength(meta),
            isContested: false,
            isAiGenerated: true,
          };
          setClaims((prev) => [...prev, claim]);
          break;
        }

        case "MODERATOR_PROMPT": {
          // Track moderator/judge actions as timeline events
          setTimeline((prev) => [...prev, {
            id: generateId(),
            type: "ruling",
            title: title || "Judicial Direction",
            description: text,
            timestamp,
            sessionTimestamp: ts,
            party: "court",
            linkedIds: [],
            isKeyMoment: true,
            isAiGenerated: true,
          }]);
          break;
        }

        default:
          break;
      }
    });
  }, [events, sessionId, processedEventIds, evidence.length]);

  // Derive verdict progress from accumulated data
  const verdictProgress: VerdictProgress = useMemo(() => {
    const prosecutionClaims = claims.filter((c) => c.party === "prosecution");
    const defenseClaims = claims.filter((c) => c.party === "defense");

    const avgProsecutionStrength = prosecutionClaims.length > 0
      ? Math.round(prosecutionClaims.reduce((sum, c) => sum + c.strength, 0) / prosecutionClaims.length)
      : 0;
    const avgDefenseStrength = defenseClaims.length > 0
      ? Math.round(defenseClaims.reduce((sum, c) => sum + c.strength, 0) / defenseClaims.length)
      : 0;

    // Determine completed phases based on data patterns
    const completedPhases: TrialPhase[] = [];
    const currentPhase: TrialPhase = determineCurrentPhase(claims, evidence, objections);

    const phaseOrder: TrialPhase[] = [
      "opening", "prosecution-case", "defense-case", "rebuttal", "closing", "deliberation", "verdict",
    ];
    const currentIdx = phaseOrder.indexOf(currentPhase);
    phaseOrder.forEach((phase, idx) => {
      if (idx < currentIdx) {
        completedPhases.push(phase);
      }
    });

    return {
      phase: currentPhase,
      completedPhases,
      currentPhase,
      notes: generateNotes(claims, objections),
      factors: [],
      prosecutionStrength: avgProsecutionStrength,
      defenseStrength: avgDefenseStrength,
    };
  }, [claims, evidence, objections]);

  const participants = useMemo(() => Array.from(participantMap.values()), [participantMap]);

  const selectEvidence = useCallback((id: string | null) => {
    setSelectedEvidenceId(id);
  }, []);

  return {
    evidence,
    claims,
    objections,
    timeline,
    participants,
    verdictProgress,
    evidenceCount: evidence.length,
    claimCount: claims.length,
    objectionCount: objections.length,
    prosecutionClaimCount: claims.filter((c) => c.party === "prosecution").length,
    defenseClaimCount: claims.filter((c) => c.party === "defense").length,
    isConnected,
    selectedEvidenceId,
    selectEvidence,
  };
}

// =============================================================================
// Helper Functions (Private)
// =============================================================================

function extractClaimType(meta: Record<string, unknown>): LegalClaim["type"] {
  const type = meta.claimType as string | undefined;
  if (type === "allegation") return "allegation";
  if (type === "defense") return "defense";
  if (type === "rebuttal") return "rebuttal";
  return "claim";
}

function determineCurrentPhase(
  claims: LegalClaim[],
  evidence: LegalEvidence[],
  objections: Objection[]
): TrialPhase {
  const totalItems = claims.length + evidence.length;
  if (totalItems === 0) return "opening";

  const hasDefenseClaims = claims.some((c) => c.party === "defense");
  const hasRebuttals = claims.some((c) => c.type === "rebuttal");
  const prosecutionClaims = claims.filter((c) => c.party === "prosecution").length;
  const defenseClaims = claims.filter((c) => c.party === "defense").length;

  if (hasRebuttals && prosecutionClaims > 3 && defenseClaims > 3) return "closing";
  if (hasRebuttals) return "rebuttal";
  if (hasDefenseClaims && defenseClaims > 2) return "defense-case";
  if (hasDefenseClaims) return "defense-case";
  if (prosecutionClaims > 2) return "prosecution-case";
  return "opening";
}

function generateNotes(claims: LegalClaim[], objections: Objection[]): string[] {
  const notes: string[] = [];

  const contestedClaims = claims.filter((c) => c.isContested);
  if (contestedClaims.length > 0) {
    notes.push(`${contestedClaims.length} claims are currently contested`);
  }

  const sustainedObjections = objections.filter((o) => o.ruling === "sustained");
  if (sustainedObjections.length > 0) {
    notes.push(`${sustainedObjections.length} objections sustained`);
  }

  const strongClaims = claims.filter((c) => c.strength >= 80);
  if (strongClaims.length > 0) {
    notes.push(`${strongClaims.length} strong arguments identified`);
  }

  return notes;
}

const OBJECTION_TYPE_LABELS_SHORT: Record<string, string> = {
  hearsay: "Hearsay",
  relevance: "Relevance",
  leading: "Leading",
  speculation: "Speculation",
  argumentative: "Argumentative",
  compound: "Compound",
  asked_and_answered: "Asked & Answered",
  assumes_facts: "Assumes Facts",
  character: "Character",
  foundation: "Foundation",
  other: "Other",
};

"use client";

/**
 * MediaPipe Gesture Detection Hook
 *
 * Runs Google's MediaPipe gesture recognition locally in the browser.
 * Detects hand gestures (thumbs up, peace sign, etc.) from video feed
 * and sends detections to the backend for clip triggering.
 *
 * This is completely FREE - no API calls, runs 100% locally!
 */

import { useState, useEffect, useRef, useCallback } from "react";
import { logger } from "@/lib/logger";
import { API_CONFIG } from '@/lib/config';

// Gesture categories that MediaPipe can detect
export type GestureCategory =
  | "Thumbs_Up"
  | "Thumbs_Down"
  | "Open_Palm"
  | "Victory" // Peace sign
  | "Closed_Fist"
  | "Pointing_Up"
  | "ILoveYou"
  | "None";

// Map MediaPipe gesture names to user-friendly labels
const GESTURE_LABELS: Record<string, string> = {
  Thumbs_Up: "Thumbs Up",
  Thumbs_Down: "Thumbs Down",
  Open_Palm: "Open Palm",
  Victory: "Peace Sign",
  Closed_Fist: "Fist",
  Pointing_Up: "Pointing Up",
  ILoveYou: "I Love You",
};

export interface GestureDetection {
  gesture: GestureCategory;
  label: string;
  confidence: number;
  handedness: "Left" | "Right";
}

export interface UseMediaPipeGesturesOptions {
  /** Video element to analyze */
  videoRef: React.RefObject<HTMLVideoElement | null>;
  /** Gestures to detect (if empty, detects all) */
  enabledGestures?: string[];
  /** Minimum confidence threshold (0-1) */
  confidenceThreshold?: number;
  /** How often to process frames (ms) */
  processingInterval?: number;
  /** Callback when gesture is detected */
  onGestureDetected?: (detection: GestureDetection) => void;
  /** Whether detection is enabled */
  enabled?: boolean;
}

export interface UseMediaPipeGesturesResult {
  isLoading: boolean;
  isReady: boolean;
  error: string | null;
  currentGesture: GestureDetection | null;
  lastDetection: GestureDetection | null;
  detectionCount: number;
}

// MediaPipe CDN URLs
const MEDIAPIPE_CDN = "https://cdn.jsdelivr.net/npm/@mediapipe";
const GESTURE_RECOGNIZER_TASK = `${MEDIAPIPE_CDN}/tasks-vision@0.10.8/wasm`;

export function useMediaPipeGestures(
  options: UseMediaPipeGesturesOptions
): UseMediaPipeGesturesResult {
  const {
    videoRef,
    enabledGestures = [],
    confidenceThreshold = 0.7,
    processingInterval = 100,
    onGestureDetected,
    enabled = true,
  } = options;

  const [isLoading, setIsLoading] = useState(true);
  const [isReady, setIsReady] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [currentGesture, setCurrentGesture] = useState<GestureDetection | null>(null);
  const [lastDetection, setLastDetection] = useState<GestureDetection | null>(null);
  const [detectionCount, setDetectionCount] = useState(0);

  // Refs for MediaPipe instances
  const gestureRecognizerRef = useRef<any>(null);
  const animationFrameRef = useRef<number | null>(null);
  const lastProcessTimeRef = useRef<number>(0);
  const lastGestureRef = useRef<string | null>(null);
  const gestureHoldStartRef = useRef<number | null>(null);

  // Minimum hold time to confirm gesture (prevents accidental triggers)
  const GESTURE_HOLD_TIME_MS = 500;

  // Load MediaPipe
  useEffect(() => {
    if (!enabled) return;

    let mounted = true;

    async function loadMediaPipe() {
      try {
        setIsLoading(true);
        setError(null);

        // Dynamically import MediaPipe tasks-vision
        const vision = await import("@mediapipe/tasks-vision");
        const { GestureRecognizer, FilesetResolver } = vision;

        // Load the vision WASM files
        const wasmFileset = await FilesetResolver.forVisionTasks(GESTURE_RECOGNIZER_TASK);

        // Create gesture recognizer
        const gestureRecognizer = await GestureRecognizer.createFromOptions(wasmFileset, {
          baseOptions: {
            modelAssetPath: `${MEDIAPIPE_CDN}/tasks-vision@0.10.8/gesture_recognizer.task`,
            delegate: "GPU", // Use GPU for better performance
          },
          runningMode: "VIDEO",
          numHands: 2,
        });

        if (mounted) {
          gestureRecognizerRef.current = gestureRecognizer;
          setIsReady(true);
          setIsLoading(false);
          logger.debug("[MediaPipe] Gesture recognizer loaded successfully");
        }
      } catch (err) {
        logger.error("[MediaPipe] Failed to load:", err);
        if (mounted) {
          setError(err instanceof Error ? err.message : "Failed to load MediaPipe");
          setIsLoading(false);
        }
      }
    }

    loadMediaPipe();

    return () => {
      mounted = false;
      if (gestureRecognizerRef.current) {
        gestureRecognizerRef.current.close();
        gestureRecognizerRef.current = null;
      }
    };
  }, [enabled]);

  // Process video frames
  const processFrame = useCallback(() => {
    if (!gestureRecognizerRef.current || !videoRef.current || !enabled) {
      animationFrameRef.current = requestAnimationFrame(processFrame);
      return;
    }

    const video = videoRef.current;
    const now = performance.now();

    // Throttle processing
    if (now - lastProcessTimeRef.current < processingInterval) {
      animationFrameRef.current = requestAnimationFrame(processFrame);
      return;
    }

    // Check if video is ready
    if (video.readyState < 2) {
      animationFrameRef.current = requestAnimationFrame(processFrame);
      return;
    }

    lastProcessTimeRef.current = now;

    try {
      // Run gesture recognition
      const results = gestureRecognizerRef.current.recognizeForVideo(video, now);

      if (results.gestures && results.gestures.length > 0) {
        // Get the most confident gesture
        const gesture = results.gestures[0][0];
        const handedness = results.handedness[0][0];

        const gestureName = gesture.categoryName as GestureCategory;
        const confidence = gesture.score;

        // Check if gesture meets threshold
        if (confidence >= confidenceThreshold && gestureName !== "None") {
          // Check if gesture is enabled (if filter is set)
          const label = GESTURE_LABELS[gestureName] || gestureName;
          const isEnabled =
            enabledGestures.length === 0 ||
            enabledGestures.some(
              (g) => g.toLowerCase() === label.toLowerCase() || g === gestureName
            );

          if (isEnabled) {
            // Track gesture hold time
            if (lastGestureRef.current === gestureName) {
              // Same gesture - check hold time
              if (gestureHoldStartRef.current) {
                const holdTime = now - gestureHoldStartRef.current;
                if (holdTime >= GESTURE_HOLD_TIME_MS) {
                  // Gesture held long enough - trigger!
                  const detection: GestureDetection = {
                    gesture: gestureName,
                    label,
                    confidence,
                    handedness: handedness.categoryName as "Left" | "Right",
                  };

                  setCurrentGesture(detection);
                  setLastDetection(detection);
                  setDetectionCount((c) => c + 1);

                  // Notify callback
                  if (onGestureDetected) {
                    onGestureDetected(detection);
                  }

                  // Reset hold tracking to prevent repeat triggers
                  gestureHoldStartRef.current = null;
                  lastGestureRef.current = null;

                  logger.debug(
                    `[MediaPipe] Gesture detected: ${label} (${(confidence * 100).toFixed(1)}%)`
                  );
                }
              }
            } else {
              // New gesture - start hold timer
              lastGestureRef.current = gestureName;
              gestureHoldStartRef.current = now;
            }
          }
        } else {
          // No valid gesture - reset
          setCurrentGesture(null);
          lastGestureRef.current = null;
          gestureHoldStartRef.current = null;
        }
      } else {
        // No hands detected
        setCurrentGesture(null);
        lastGestureRef.current = null;
        gestureHoldStartRef.current = null;
      }
    } catch (err) {
      logger.error("[MediaPipe] Processing error:", err);
    }

    animationFrameRef.current = requestAnimationFrame(processFrame);
  }, [
    videoRef,
    enabled,
    processingInterval,
    confidenceThreshold,
    enabledGestures,
    onGestureDetected,
  ]);

  // Start/stop processing loop
  useEffect(() => {
    if (isReady && enabled) {
      animationFrameRef.current = requestAnimationFrame(processFrame);
    }

    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
        animationFrameRef.current = null;
      }
    };
  }, [isReady, enabled, processFrame]);

  return {
    isLoading,
    isReady,
    error,
    currentGesture,
    lastDetection,
    detectionCount,
  };
}

/**
 * Hook to send MediaPipe detections to backend via WebSocket
 */
export function useMediaPipeWithBackend(
  sessionId: string | null,
  options: Omit<UseMediaPipeGesturesOptions, "onGestureDetected">
) {
  const wsRef = useRef<WebSocket | null>(null);
  const wsBase = API_CONFIG.desktopWsUrl;

  // Connect to WebSocket
  useEffect(() => {
    if (!sessionId) return;

    const ws = new WebSocket(wsBase);

    ws.onopen = () => {
      logger.debug("[MediaPipe] WebSocket connected for gesture events");
    };

    ws.onerror = (err) => {
      logger.error("[MediaPipe] WebSocket error:", err);
    };

    wsRef.current = ws;

    return () => {
      ws.close();
      wsRef.current = null;
    };
  }, [sessionId, wsBase]);

  // Handle gesture detection
  const handleGestureDetected = useCallback(
    (detection: GestureDetection) => {
      if (!wsRef.current || wsRef.current.readyState !== WebSocket.OPEN) {
        return;
      }

      // Send detection to backend
      const message = {
        type: "MEDIAPIPE_DETECTION",
        sessionId,
        payload: {
          detections: [
            {
              label: detection.label,
              confidence: detection.confidence,
            },
          ],
        },
      };

      wsRef.current.send(JSON.stringify(message));
      logger.debug(`[MediaPipe] Sent detection to backend: ${detection.label}`);
    },
    [sessionId]
  );

  return useMediaPipeGestures({
    ...options,
    onGestureDetected: handleGestureDetected,
  });
}

/**
 * Custom hook for managing moments (markers/highlights) with API integration and real-time updates
 *
 * This hook:
 * - Fetches moments from backend API for a specific session
 * - Listens for WebSocket events for real-time moment updates (MOMENT_MARKER)
 * - Provides loading and error states
 * - Integrates with auth context for authenticated API calls
 * - Provides createMoment function for adding new moments
 */

import { useState, useEffect, useCallback, useRef } from "react";
import {
  getSessionMoments,
  createMoment as apiCreateMoment,
  deleteMoment as apiDeleteMoment,
  type MomentInfo,
  type MomentType,
  type PaginationInfo,
} from "@/lib/api/moments";
import { useWebSocket } from "@/contexts/WebSocketContext";
import { useAuth } from "@/lib/contexts/AuthContext";
import { logger } from "@/lib/logger";

/**
 * Moment with display-friendly properties
 * Compatible with the Moment type from streamer dashboard types
 */
export interface Moment {
  id: string;
  sessionId: string;
  type: MomentType;
  label: string;
  description?: string;
  timestamp: number; // in seconds from session start
  clipId?: string;
  createdAt: string;
  // Formatted timestamp for display
  formattedTime: string;
}

/**
 * Return type for useMoments hook
 */
export interface UseMomentsReturn {
  moments: Moment[];
  pagination: PaginationInfo;
  isLoading: boolean;
  error: string | null;
  isConnected: boolean;

  // Actions
  refresh: () => Promise<void>;
  createMoment: (moment: {
    type?: MomentType;
    label: string;
    description?: string;
    timestamp: number;
    clipId?: string;
  }) => Promise<Moment>;
  deleteMoment: (momentId: string) => Promise<void>;
  loadMore: () => Promise<void>;
  clearError: () => void;

  // Derived data
  momentsByType: Record<MomentType, Moment[]>;
  momentCount: number;
}

/**
 * Format seconds to MM:SS or HH:MM:SS format
 */
function formatTimestamp(seconds: number): string {
  const hrs = Math.floor(seconds / 3600);
  const mins = Math.floor((seconds % 3600) / 60);
  const secs = Math.floor(seconds % 60);

  if (hrs > 0) {
    return `${hrs}:${mins.toString().padStart(2, "0")}:${secs.toString().padStart(2, "0")}`;
  }
  return `${mins}:${secs.toString().padStart(2, "0")}`;
}

/**
 * Transform API moment to frontend format
 */
function transformMoment(apiMoment: MomentInfo): Moment {
  return {
    ...apiMoment,
    formattedTime: formatTimestamp(apiMoment.timestamp),
  };
}

/**
 * Hook for fetching and managing moments for a specific session
 *
 * Features:
 * - Fetches moments from backend API
 * - Real-time WebSocket updates for new moments
 * - Automatic data refresh on moment events
 * - Error handling with user-friendly messages
 * - Authentication via AuthContext
 * - Create moment functionality
 *
 * @param sessionId - The session ID to fetch moments for
 * @param options - Configuration options
 */
export function useMoments(
  sessionId: string,
  options: {
    limit?: number;
    autoRefresh?: boolean;
  } = {}
): UseMomentsReturn {
  const { limit = 100, autoRefresh = true } = options;

  const [moments, setMoments] = useState<Moment[]>([]);
  const [pagination, setPagination] = useState<PaginationInfo>({
    limit,
    offset: 0,
    total: 0,
  });
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const isLoadingRef = useRef(false);

  // Get auth context for access token
  const { accessToken } = useAuth();

  // WebSocket for real-time updates
  const { isConnected, moments: wsMomentEvents } = useWebSocket();

  /**
   * Load moments from the backend API
   */
  const loadMoments = useCallback(
    async (offset = 0, append = false) => {
      if (!sessionId) {
        setIsLoading(false);
        return;
      }

      // Prevent concurrent fetches
      if (isLoadingRef.current) return;
      isLoadingRef.current = true;

      try {
        setError(null);
        if (!append) {
          setIsLoading(true);
        }

        // Fetch moments from the backend API
        const result = await getSessionMoments(
          sessionId,
          { limit, offset },
          accessToken || undefined
        );

        const transformedMoments = result.moments.map(transformMoment);

        if (append) {
          setMoments((prev) => [...prev, ...transformedMoments]);
        } else {
          setMoments(transformedMoments);
        }

        setPagination(result.pagination);
      } catch (err) {
        logger.error("Failed to load moments:", err);
        setError(err instanceof Error ? err.message : "Failed to load moments");
        // Keep existing data on error
      } finally {
        setIsLoading(false);
        isLoadingRef.current = false;
      }
    },
    [sessionId, limit, accessToken]
  );

  /**
   * Refresh moments (reload from offset 0)
   */
  const refresh = useCallback(async () => {
    await loadMoments(0, false);
  }, [loadMoments]);

  /**
   * Load more moments (pagination)
   */
  const loadMore = useCallback(async () => {
    const nextOffset = pagination.offset + pagination.limit;
    if (nextOffset < pagination.total) {
      await loadMoments(nextOffset, true);
    }
  }, [loadMoments, pagination]);

  /**
   * Create a new moment
   */
  const createMoment = useCallback(
    async (momentData: {
      type?: MomentType;
      label: string;
      description?: string;
      timestamp: number;
      clipId?: string;
    }): Promise<Moment> => {
      try {
        setError(null);
        const created = await apiCreateMoment(
          sessionId,
          momentData,
          accessToken || undefined
        );

        const newMoment = transformMoment(created);

        // Add to local state optimistically (at the correct position by timestamp)
        setMoments((prev) => {
          const updated = [...prev, newMoment];
          return updated.sort((a, b) => a.timestamp - b.timestamp);
        });

        setPagination((prev) => ({
          ...prev,
          total: prev.total + 1,
        }));

        return newMoment;
      } catch (err) {
        const errorMsg = err instanceof Error ? err.message : "Failed to create moment";
        setError(errorMsg);
        throw new Error(errorMsg);
      }
    },
    [sessionId, accessToken]
  );

  /**
   * Delete a moment by ID
   */
  const deleteMoment = useCallback(
    async (momentId: string): Promise<void> => {
      try {
        setError(null);
        await apiDeleteMoment(sessionId, momentId, accessToken || undefined);

        // Remove from local state optimistically
        setMoments((prev) => prev.filter((m) => m.id !== momentId));
        setPagination((prev) => ({
          ...prev,
          total: Math.max(0, prev.total - 1),
        }));
      } catch (err) {
        const errorMsg = err instanceof Error ? err.message : "Failed to delete moment";
        setError(errorMsg);
        throw new Error(errorMsg);
      }
    },
    [sessionId, accessToken]
  );

  /**
   * Clear error state
   */
  const clearError = useCallback(() => {
    setError(null);
  }, []);

  /**
   * Initial data load
   */
  useEffect(() => {
    loadMoments(0, false);
  }, [loadMoments]);

  /**
   * Auto-refresh when WebSocket moment events arrive
   */
  useEffect(() => {
    if (!autoRefresh) return;

    // Check for moment-related events
    if (wsMomentEvents.length > 0) {
      // Debounced refresh to avoid excessive API calls
      const timer = setTimeout(() => {
        loadMoments(0, false);
      }, 500);

      return () => clearTimeout(timer);
    }
  }, [wsMomentEvents, autoRefresh, loadMoments]);

  /**
   * Compute derived data - moments grouped by type
   */
  const momentsByType = moments.reduce<Record<MomentType, Moment[]>>(
    (acc, moment) => {
      const type = moment.type as MomentType;
      if (!acc[type]) {
        acc[type] = [];
      }
      acc[type].push(moment);
      return acc;
    },
    {
      hype: [],
      qa: [],
      sponsor: [],
      clip: [],
      highlight: [],
      marker: [],
    }
  );

  return {
    moments,
    pagination,
    isLoading,
    error,
    isConnected,
    refresh,
    createMoment,
    deleteMoment,
    loadMore,
    clearError,
    momentsByType,
    momentCount: moments.length,
  };
}

/**
 * Hook for fetching a single moment by ID
 * Currently not needed but included for API completeness
 */
export function useMoment(momentId: string): {
  moment: Moment | null;
  isLoading: boolean;
  error: string | null;
} {
  // For now, return empty as we don't have a single moment endpoint
  // This is a placeholder for future implementation
  return {
    moment: null,
    isLoading: false,
    error: null,
  };
}

/**
 * Custom hook for managing sessions with API integration and real-time updates
 *
 * This hook:
 * - Fetches sessions from backend API on mount
 * - Connects to WebSocket for real-time events
 * - Automatically refreshes session data when new events arrive
 * - Integrates with auth context for authenticated API calls
 */

import { useState, useEffect, useCallback, useRef } from "react";
import {
  getSessions,
  getSessionById,
  startSession as apiStartSession,
  endSession as apiEndSession,
  updateSession as apiUpdateSession,
  deleteSession as apiDeleteSession,
  getSessionOutputs as apiGetSessionOutputs,
  forceStopSession as apiForceStopSession,
  type SessionListItem,
  type StartSessionConfig,
  type StartSessionResponse,
  type SessionOutput,
  type PaginationInfo,
} from "@/lib/api/sessions";
import { useWebSocket } from "@/contexts/WebSocketContext";
import { useAuth } from "@/lib/contexts/AuthContext";
import { ApiError } from "@/lib/api/client";
import { type Session, formatDuration } from "@/lib/stores/sessions";
import { WORKFLOW_TYPES, CAPTURE_MODES, type WorkflowType, type CaptureMode } from "@/lib/constants";
import { API_CONFIG } from '@/lib/config';
import { logger } from "@/lib/logger";

/**
 * Filters for session queries
 */
export interface SessionFilters {
  workflow?: string;
  status?: "live" | "ended";
  limit?: number;
  offset?: number;
}

/**
 * Return type for useSessions hook
 */
export interface UseSessionsReturn {
  sessions: Session[];
  activeSession: Session | null;
  isLoading: boolean;
  error: string | null;
  isConnected: boolean;
  isAuthenticated: boolean;
  pagination: PaginationInfo;

  // Actions
  createSession: (config: StartSessionConfig) => Promise<StartSessionResponse>;
  endSession: (id: string) => Promise<void>;
  updateSession: (id: string, updates: { title?: string; participants?: string[] }) => Promise<void>;
  deleteSession: (id: string) => Promise<void>;
  getSessionOutputs: (id: string) => Promise<SessionOutput[]>;
  refetch: () => Promise<void>;
  refreshSessions: () => Promise<void>;
  forceStop: () => Promise<void>;
  clearError: () => void;
}

/**
 * Map API workflow values to frontend workflow types
 * The API uses shared package types which differ from frontend constants
 */
function mapApiWorkflow(apiWorkflow: string): WorkflowType {
  const workflowMap: Record<string, WorkflowType> = {
    streamer: WORKFLOW_TYPES.CONTENT_CREATOR,
    content_creator: WORKFLOW_TYPES.CONTENT_CREATOR,
    podcast: WORKFLOW_TYPES.PODCAST,
    writers_room: WORKFLOW_TYPES.WRITERS_CORNER,
    writers_corner: WORKFLOW_TYPES.WRITERS_CORNER,
    brainstorm: WORKFLOW_TYPES.MIND_MAP,
    mind_map: WORKFLOW_TYPES.MIND_MAP,
    debate: WORKFLOW_TYPES.DEBATE_ROOM,
    debate_room: WORKFLOW_TYPES.DEBATE_ROOM,
    court_session: WORKFLOW_TYPES.COURT_SESSION,
    script_studio: WORKFLOW_TYPES.SCRIPT_STUDIO,
  };
  return workflowMap[apiWorkflow] || WORKFLOW_TYPES.CONTENT_CREATOR;
}

/**
 * Map API capture mode values to frontend capture mode types
 */
function mapApiCaptureMode(apiCaptureMode: string): CaptureMode {
  const captureModeMap: Record<string, CaptureMode> = {
    av: CAPTURE_MODES.AUDIO_VIDEO,
    audio_video: CAPTURE_MODES.AUDIO_VIDEO,
    audio: CAPTURE_MODES.AUDIO,
    video: CAPTURE_MODES.VIDEO,
  };
  return captureModeMap[apiCaptureMode] || CAPTURE_MODES.AUDIO_VIDEO;
}

/**
 * Convert API SessionListItem to frontend Session format
 */
function mapApiSessionToSession(apiSession: SessionListItem): Session {
  const startedAt = new Date(apiSession.startedAt);
  const endedAt = apiSession.endedAt ? new Date(apiSession.endedAt) : null;

  // Calculate duration
  const durationMs = endedAt
    ? endedAt.getTime() - startedAt.getTime()
    : Date.now() - startedAt.getTime();

  return {
    id: apiSession.id,
    name: apiSession.title || "Untitled Session",
    workflow: mapApiWorkflow(apiSession.workflow),
    captureMode: mapApiCaptureMode(apiSession.captureMode),
    // Map isActive to "live" for active sessions, "ended" for completed sessions
    // This matches the dashboard page expectations for session status
    status: apiSession.isActive ? "live" : "ended",
    startedAt: apiSession.startedAt,
    endedAt: apiSession.endedAt || undefined,
    duration: formatDuration(durationMs),
    clipCount: apiSession.counts.clips,
    outputCount: apiSession.counts.outputs,
  };
}

/**
 * Hook for managing sessions with API integration
 *
 * Features:
 * - Fetches sessions from backend API
 * - Real-time WebSocket updates
 * - Automatic data refresh on events
 * - Error handling with user-friendly messages
 * - Authentication via AuthContext
 * - Support for filtering by workflow and status
 *
 * @param filters - Optional filters for sessions (workflow, status, limit, offset)
 * @param autoConnect - Whether to connect WebSocket on mount (default: true)
 */
export function useSessions(
  filters?: SessionFilters,
  autoConnect = true
): UseSessionsReturn {
  const [sessions, setSessions] = useState<Session[]>([]);
  const [activeSession, setActiveSession] = useState<Session | null>(null);
  const [pagination, setPagination] = useState<PaginationInfo>({
    limit: filters?.limit || 50,
    offset: filters?.offset || 0,
    total: 0,
  });
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const isLoadingRef = useRef(false);

  // Get auth context for access token
  const { accessToken, isAuthenticated } = useAuth();

  const {
    connect,
    disconnect,
    isConnected,
    events,
    clearEvents
  } = useWebSocket();

  /**
   * Load sessions from the backend API
   */
  const loadSessions = useCallback(async () => {
    // Prevent concurrent fetches
    if (isLoadingRef.current) return;
    isLoadingRef.current = true;

    try {
      setError(null);

      const limit = filters?.limit || 50;
      const offset = filters?.offset || 0;

      // Build server-side filters
      const serverFilters: { workflow?: string; active?: boolean } = {};
      if (filters?.workflow) {
        serverFilters.workflow = filters.workflow;
      }
      if (filters?.status === "live") {
        serverFilters.active = true;
      } else if (filters?.status === "ended") {
        serverFilters.active = false;
      }

      // Fetch sessions from the backend API with filters (pass auth token if available)
      const { sessions: apiSessions, pagination: paginationInfo } = await getSessions(
        limit,
        offset,
        accessToken || undefined,
        serverFilters
      );

      // Map API response to frontend Session format
      const mappedSessions = apiSessions.map(mapApiSessionToSession);

      setSessions(mappedSessions);
      setPagination(paginationInfo);

      // Find the active session (if any)
      const active = mappedSessions.find((s) => s.status === "live") || null;
      setActiveSession(active);
    } catch (err) {
      logger.error("Failed to load sessions:", err);
      setError(err instanceof Error ? err.message : "Failed to load sessions");
      // Keep existing data on error
    } finally {
      setIsLoading(false);
      isLoadingRef.current = false;
    }
  }, [accessToken, filters]);

  /**
   * Create a new session
   * Calls API /session/start and refreshes the session list
   */
  const createSession = useCallback(async (config: StartSessionConfig): Promise<StartSessionResponse> => {
    try {
      setError(null);

      // Call backend API with auth token
      const response = await apiStartSession(config, accessToken || undefined);

      // Refresh sessions list from API
      await loadSessions();

      return response;
    } catch (err: any) {
      const isConflict = (err instanceof ApiError && err.status === 409) || err.status === 409;

      if (isConflict) {
        // Special handling for 409 Conflict
        const body = err.body || {};
        const msg = body.error || "A session is already active. You must stop it before starting a new one.";
        setError(msg);
        throw new Error(msg);
      }

      const errorMsg = err instanceof Error ? err.message : "Failed to create session";
      setError(errorMsg);
      throw new Error(errorMsg);
    }
  }, [loadSessions, accessToken]);

  /**
   * Force-stop the current session (clear in-memory state)
   * Calls API /session/force-stop
   */
  const forceStop = useCallback(async (): Promise<void> => {
    try {
      setError(null);
      setIsLoading(true);

      await apiForceStopSession(accessToken || undefined);

      // Refresh sessions list from API
      await loadSessions();
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : "Failed to force-stop session";
      setError(errorMsg);
      throw new Error(errorMsg);
    } finally {
      setIsLoading(false);
    }
  }, [loadSessions, accessToken]);

  /**
   * End a session
   * Calls API /session/stop and refreshes the session list
   */
  const endSession = useCallback(async (id: string): Promise<void> => {
    try {
      setError(null);

      // Call backend API with auth token (stops the active session)
      await apiEndSession(id, accessToken || undefined);

      // Refresh sessions list from API
      await loadSessions();
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : "Failed to end session";
      setError(errorMsg);
      throw new Error(errorMsg);
    }
  }, [loadSessions, accessToken]);

  /**
   * Update a session's metadata
   * Calls API PATCH /api/sessions/:id and refreshes the session list
   */
  const updateSession = useCallback(async (
    id: string,
    updates: { title?: string; participants?: string[] }
  ): Promise<void> => {
    try {
      setError(null);

      // Call backend API with auth token
      await apiUpdateSession(id, updates, accessToken || undefined);

      // Refresh sessions list from API
      await loadSessions();
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : "Failed to update session";
      setError(errorMsg);
      throw new Error(errorMsg);
    }
  }, [loadSessions, accessToken]);

  /**
   * Delete a session
   * Calls API DELETE /api/sessions/:id and refreshes the session list
   */
  const deleteSession = useCallback(async (id: string): Promise<void> => {
    try {
      setError(null);

      // Call backend API with auth token
      await apiDeleteSession(id, accessToken || undefined);

      // Refresh sessions list from API
      await loadSessions();
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : "Failed to delete session";
      setError(errorMsg);
      throw new Error(errorMsg);
    }
  }, [loadSessions, accessToken]);

  /**
   * Get outputs for a specific session
   * Calls API GET /api/sessions/:id/outputs
   */
  const getSessionOutputs = useCallback(async (id: string): Promise<SessionOutput[]> => {
    try {
      setError(null);

      // Call backend API with auth token
      return await apiGetSessionOutputs(id, accessToken || undefined);
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : "Failed to get session outputs";
      setError(errorMsg);
      throw new Error(errorMsg);
    }
  }, [accessToken]);

  /**
   * Clear error state
   */
  const clearError = useCallback(() => {
    setError(null);
  }, []);

  /**
   * Connect WebSocket on mount if autoConnect is true
   */
  useEffect(() => {
    if (autoConnect) {
      const wsUrl = API_CONFIG.wsUrl;
      connect();

      return () => {
        disconnect();
        clearEvents();
      };
    }
  }, [autoConnect, connect, disconnect, clearEvents]);

  /**
   * Initial data load
   */
  useEffect(() => {
    loadSessions();
  }, [loadSessions]);

  /**
   * Auto-refresh when WebSocket events arrive
   * Debounced to avoid excessive refreshes
   */
  useEffect(() => {
    if (events.length > 0) {
      const timer = setTimeout(() => {
        loadSessions();
      }, 1000); // 1 second debounce

      return () => clearTimeout(timer);
    }
  }, [events.length, loadSessions]);

  return {
    sessions,
    activeSession,
    pagination,
    isLoading,
    error,
    isConnected,
    isAuthenticated,
    createSession,
    endSession,
    updateSession,
    deleteSession,
    getSessionOutputs,
    refetch: loadSessions,
    refreshSessions: loadSessions,
    forceStop,
    clearError,
  };
}

/**
 * Return type for useSession hook
 */
export interface UseSessionReturn {
  session: Session | null;
  isLoading: boolean;
  error: string | null;
  refresh: () => Promise<void>;
}

/**
 * Hook for fetching a single session by ID
 *
 * @param id - The session ID to fetch
 */
export function useSession(id: string): UseSessionReturn {
  const [session, setSession] = useState<Session | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Get auth context for access token
  const { accessToken } = useAuth();

  const loadSession = useCallback(async () => {
    if (!id) {
      setIsLoading(false);
      return;
    }

    try {
      setError(null);
      setIsLoading(true);

      // Pass auth token to API call
      const apiSession = await getSessionById(id, accessToken || undefined);
      setSession(mapApiSessionToSession(apiSession));
    } catch (err) {
      logger.error("Failed to load session:", err);
      setError(err instanceof Error ? err.message : "Failed to load session");
      setSession(null);
    } finally {
      setIsLoading(false);
    }
  }, [id, accessToken]);

  useEffect(() => {
    loadSession();
  }, [loadSession]);

  return {
    session,
    isLoading,
    error,
    refresh: loadSession,
  };
}

