      const error = await errorPromise;
      expect(error).toMatchObject({
        body: { message: `Request timed out after ${customTimeout}ms` },
      });
    });

    it("should not confuse AbortError with other errors", async () => {
      setFetchMock(vi.fn().mockRejectedValue(new Error("Regular network error")));

      await expect(apiClient.get<TestData>("/test")).rejects.toMatchObject({
        statusText: "Network Error",
        body: { message: "Regular network error" },
      });
    });
  });

  describe("Edge cases", () => {
    it("should handle timeout of 0 (immediate timeout)", async () => {
      const abortSpy = vi.spyOn(AbortController.prototype, "abort");

      setFetchMock(createAbortAwareFetchMock());

      const errorPromise = captureRejection(
        apiClient.get<TestData>("/test", { timeout: 0, params: {} })
      );

      await vi.advanceTimersByTimeAsync(0);
      expect(abortSpy).toHaveBeenCalled();

      const error = await errorPromise;
      expect(error).toBeInstanceOf(ApiError);
    });

    it("should handle very long timeout values", async () => {
      setFetchMock(vi.fn().mockResolvedValue({
        ok: true,
        status: 200,
        headers: new Headers({ "content-type": "application/json" }),
        json: async () => ({ id: "1", name: "Test" }),
      }));

      const result = await apiClient.get<TestData>("/test", {
        timeout: 999999999,
        params: {},
      });

      expect(result).toEqual({ id: "1", name: "Test" });
    });

    it("should handle requests that complete just before timeout", async () => {
      const abortSpy = vi.spyOn(AbortController.prototype, "abort");

      setFetchMock(vi.fn(
        () =>
          new Promise((resolve) => {
            setTimeout(() => {
              resolve({
                ok: true,
                status: 200,
                headers: new Headers({ "content-type": "application/json" }),
                json: async () => ({ id: "1", name: "Test" }),
              });
            }, 4999);
          })
      ));

      const requestPromise = apiClient.get<TestData>("/test", { timeout: 5000, params: {} });

      await vi.advanceTimersByTimeAsync(4999);
      expect(abortSpy).not.toHaveBeenCalled();

      const result = await requestPromise;
      expect(result).toEqual({ id: "1", name: "Test" });
    });
  });

  describe("Integration with other RequestOptions", () => {
    it("should work with custom headers and timeout", async () => {
      let capturedHeaders: Headers | undefined;

      setFetchMock(vi.fn((url: any, options: any) => {
        capturedHeaders = new Headers(options?.headers);
        return Promise.resolve({
          ok: true,
          status: 200,
          headers: new Headers({ "content-type": "application/json" }),
          json: async () => ({ id: "1", name: "Test" }),
        });
      }));

      await apiClient.get<TestData>("/test", {
        headers: { "X-Custom": "value" },
        timeout: 5000,
      });

      expect(capturedHeaders?.get("X-Custom")).toBe("value");
    });

    it("should work with params and timeout", async () => {
      let capturedUrl: string | undefined;

      setFetchMock(vi.fn((url: any) => {
        capturedUrl = url as string;
        return Promise.resolve({
          ok: true,
          status: 200,
          headers: new Headers({ "content-type": "application/json" }),
          json: async () => ({ id: "1", name: "Test" }),
        });
      }));

      await apiClient.get<TestData>("/test", {
        params: { page: 1, limit: 10 },
        timeout: 5000,
      });

      expect(capturedUrl).toContain("page=1");
      expect(capturedUrl).toContain("limit=10");
    });

    it("should work with skipValidation and timeout", async () => {
      setFetchMock(vi.fn().mockResolvedValue({
        ok: true,
        status: 200,
        headers: new Headers({ "content-type": "application/json" }),
        json: async () => ({ invalid: "data" }),
      }));

      // Should not throw validation error when skipValidation is true
      const result = await apiClient.get<TestData>("/test", testSchema, {
        skipValidation: true,
        timeout: 5000,
      });

      expect(result).toEqual({ invalid: "data" });
    });
  });
});

/**
 * Export API methods for FluxBoard
 *
 * Handles video/content export operations including:
 * - Starting export jobs
 * - Polling for export progress
 * - Retrieving download URLs
 */

import { apiClient } from "./client";
import type {
  SocialPlatform,
  ExportFormatOptions,
} from "@/components/export/types";
import { logger } from "@/lib/logger";

// ============================================================
// API Request/Response Types
// ============================================================

/**
 * Backend platform enum values (uppercase)
 * Maps frontend lowercase platform IDs to backend UPPERCASE enum values
 */
const PLATFORM_API_MAP: Record<SocialPlatform, string> = {
  x: "TWITTER",
  linkedin: "LINKEDIN",
  instagram: "INSTAGRAM",
  tiktok: "TIKTOK",
  youtube: "YOUTUBE",
} as const;

/**
 * Backend format enum values (uppercase)
 */
const FORMAT_API_MAP: Record<string, string> = {
  mp4: "MP4",
  mov: "MOV",
  webm: "WEBM",
} as const;

/**
 * Transform frontend platform ID to backend API enum value
 */
function toApiPlatform(platform: SocialPlatform): string {
  return PLATFORM_API_MAP[platform] || platform.toUpperCase();
}

/**
 * Transform frontend format to backend API enum value
 */
function toApiFormat(format: string): string {
  return FORMAT_API_MAP[format.toLowerCase()] || format.toUpperCase();
}

/**
 * Request body for starting an export job
 */
export interface StartExportRequest {
  sessionId: string;
  contentId?: string;
  clipId?: string;
  platforms: SocialPlatform[];
  caption?: string;
  hashtags?: string[];
  formatOptions: ExportFormatOptions;
  customFilename?: string;
}

/**
 * Backend API request format (with transformed enums)
 */
interface ApiExportClipRequest {
  clipId: string;
  format: string; // "MP4" | "WEBM" | "MOV"
  platform?: string; // "TWITTER" | "LINKEDIN" | etc.
  options?: {
    quality?: "low" | "medium" | "high" | "original";
    generateThumbnail?: boolean;
    addWatermark?: boolean;
    optimizeForPlatform?: boolean;
    targetAspectRatio?: string;
  };
}

/**
 * Backend API request format for posts
 */
interface ApiExportPostRequest {
  text: string;
  platform: string; // "TWITTER" | "LINKEDIN" | etc.
  sessionId?: string;
  clipId?: string;
  options?: {
    copyToClipboard?: boolean;
    saveToFile?: boolean;
    optimizeHashtags?: boolean;
    addTimestamps?: boolean;
    createThread?: boolean;
  };
}

/**
 * Response from starting an export job
 */
export interface StartExportResponse {
  exportId: string;
  status: ExportJobStatus;
  createdAt: string;
}

/**
 * Export job status enum
 */
export type ExportJobStatus =
  | "pending"
  | "preparing"
  | "processing"
  | "encoding"
  | "completed"
  | "failed";

/**
 * Export status response from the API
 */
export interface ExportStatusResponse {
  exportId: string;
  status: ExportJobStatus;
  progress: number; // 0-100
  message?: string;
  error?: string;
  downloadUrl?: string;
  filename?: string;
  fileSize?: number;
  completedAt?: string;
}

/**
 * Download URL response
 */
export interface ExportDownloadResponse {
  downloadUrl: string;
  filename: string;
  fileSize: number;
  expiresAt?: string;
}

/**
 * Standard response shape from the export API endpoints
 */
interface ExportApiResponse {
  success: boolean;
  data: {
    id: string;
    status: string;
    createdAt?: string;
    progress?: number;
    filePath?: string;
    fileSize?: number;
    completedAt?: string;
    errorMessage?: string;
    metadata?: Record<string, unknown>;
  };
}

// ============================================================
// API Methods
// ============================================================

/**
 * Start a new export job
 *
 * @param sessionId - The session ID containing the content to export
 * @param options - Export configuration options
 * @returns The export job ID and initial status
 *
 * @example
 * ```ts
 * const { exportId } = await startExport("session-123", {
 *   platforms: ["youtube", "tiktok"],
 *   formatOptions: { format: "mp4", quality: "1080p", aspectRatio: "9:16" },
 * });
 * ```
 */
export async function startExport(
  contentId: string,
  options: Omit<StartExportRequest, "sessionId" | "contentId">
): Promise<StartExportResponse> {
  const { platforms, caption, hashtags, formatOptions, customFilename } = options;

  // TODO: Implement post export support when content type detection is added.
  // Currently only clip exports are supported.

  // Prepare clip export request with enum transformations
  const apiRequest: ApiExportClipRequest = {
    clipId: contentId,
    format: toApiFormat(formatOptions.format),
    platform: platforms.length > 0 ? toApiPlatform(platforms[0]) : undefined,
    options: {
      quality: formatOptions.quality === "1080p" ? "high" :
               formatOptions.quality === "720p" ? "medium" : "high",
      generateThumbnail: true,
      addWatermark: formatOptions.includeWatermark,
      optimizeForPlatform: true,
      targetAspectRatio: formatOptions.aspectRatio,
    },
  };

  logger.debug("[export API] Sending clip export request:", apiRequest);

  // Call backend clip export endpoint
  const response = await apiClient.post<ExportApiResponse>(
    "/api/export/clip",
    apiRequest
  );

  // Transform response to match expected format
  return {
    exportId: response.data.id,
    status: mapBackendStatus(response.data.status),
    createdAt: response.data.createdAt || new Date().toISOString(),
  };
}

/**
 * Map backend status enum to frontend status type
 */
function mapBackendStatus(status: string): ExportJobStatus {
  const statusMap: Record<string, ExportJobStatus> = {
    PENDING: "pending",
    PROCESSING: "processing",
    COMPLETED: "completed",
    FAILED: "failed",
  };
  return statusMap[status] || "pending";
}

/**
 * Get the current status and progress of an export job
 *
 * @param exportId - The export job ID returned from startExport
 * @returns Current status, progress percentage, and optional download URL if completed
 *
 * @example
 * ```ts
 * const status = await getExportStatus("export-456");
 * if (status.status === "completed") {
 *   logger.debug("Download URL:", status.downloadUrl);
 * }
 * ```
 */
export async function getExportStatus(
  exportId: string
): Promise<ExportStatusResponse> {
  const response = await apiClient.get<ExportApiResponse>(
    `/api/export/${exportId}/status`
  );

  const data = response.data;

  // Calculate progress based on status
  let progress = 0;
  const status = mapBackendStatus(data.status);

  if (status === "completed") {
    progress = 100;
  } else if (status === "processing" || status === "encoding") {
    progress = data.progress || 50;
  } else if (status === "preparing") {
    progress = 25;
  }

  return {
    exportId: data.id,
    status,
    progress,
    message: data.metadata?.message as string | undefined,
    error: data.errorMessage,
    downloadUrl: data.filePath ? `/api/export/${exportId}/download` : undefined,
    filename: data.filePath ? data.filePath.split("/").pop() : undefined,
    fileSize: data.fileSize != null ? Number(data.fileSize) : undefined,
    completedAt: data.completedAt,
  };
}

/**
 * Get the download URL for a completed export
 *
 * @param exportId - The export job ID
 * @returns Download URL, filename, and file size
 * @throws ApiError if the export is not completed or has failed
 *
 * @example
 * ```ts
 * const { downloadUrl, filename } = await getExportDownloadUrl("export-456");
 * window.open(downloadUrl, "_blank");
 * ```
 */
export async function getExportDownloadUrl(
  exportId: string
): Promise<ExportDownloadResponse> {
  // Get export status first to validate completion
  const status = await getExportStatus(exportId);

  if (status.status !== "completed") {
    throw new Error("Export is not ready for download");
  }

  if (!status.downloadUrl) {
    throw new Error("Download URL not available");
  }

  return {
    downloadUrl: status.downloadUrl,
    filename: status.filename || "export.mp4",
    fileSize: status.fileSize || 0,
  };
}

// ============================================================
// Helper Functions
// ============================================================

/**
 * Map API status to user-friendly message
 */
export function getStatusMessage(status: ExportJobStatus): string {
  const messages: Record<ExportJobStatus, string> = {
    pending: "Export queued...",
    preparing: "Preparing content...",
    processing: "Processing video...",
    encoding: "Encoding for platforms...",
    completed: "Export complete!",
    failed: "Export failed",
  };
  return messages[status];
}

/**
 * Check if the export status indicates completion (success or failure)
 */
export function isExportFinished(status: ExportJobStatus): boolean {
  return status === "completed" || status === "failed";
}

/**
 * Check if the export was successful
 */
export function isExportSuccessful(status: ExportJobStatus): boolean {
  return status === "completed";
}

/**
 * Posts API methods for FluxBoard Producer Desk
 *
 * Provides API methods for managing social posts (approve, publish, schedule, delete)
 * Posts are a specialized view of outputs with category "SOCIAL_POST"
 * Enhanced with comprehensive Zod schema validation for runtime type safety
 */

import { z } from "zod";
import { apiClient, type RequestOptions } from "./client";
import { apiResponseSchema, outputInfoSchema, type OutputStatus } from "./schemas";
import type { OutputInfo } from "./outputs";

/**
 * Post status types
 */
export type PostStatus = "draft" | "approved" | "published" | "scheduled";

/**
 * Post information schema
 */
const postInfoSchema = outputInfoSchema.extend({
  status: z.enum(["draft", "approved", "published", "scheduled"]),
  scheduledFor: z.string().datetime().optional(),
});

/**
 * Post mutation response schema
 */
const postMutationResponseSchema = apiResponseSchema(
  z.object({
    post: postInfoSchema.optional(),
    output: outputInfoSchema.optional(),
    message: z.string().optional(),
  })
);

/**
 * Schedule post response schema
 */
const schedulePostResponseSchema = apiResponseSchema(
  z.object({
    post: postInfoSchema.optional(),
    output: outputInfoSchema.optional(),
    scheduledFor: z.string().datetime(),
    message: z.string().optional(),
  })
);

/**
 * Post information from the API
 */
export interface PostInfo extends Omit<OutputInfo, 'status'> {
  status: PostStatus;
  scheduledFor?: string;
}

/**
 * Create request options with optional auth header
 */
function withAuth(accessToken?: string, options: RequestOptions = {}): RequestOptions {
  if (!accessToken) return options;

  return {
    ...options,
    headers: {
      ...options.headers,
      Authorization: `Bearer ${accessToken}`,
    },
  };
}

/**
 * Approve a post (changes status from draft to approved)
 * @param postId - Post/Output ID
 * @param token - Optional auth token
 */
export async function approvePost(postId: string, token?: string): Promise<PostInfo> {
  const response = await apiClient.post(
    `/api/posts/${encodeURIComponent(postId)}/approve`,
    postMutationResponseSchema,
    {},
    withAuth(token)
  );

  const post = response.data.post || response.data.output;
  if (!post) {
    throw new Error("Post not returned from approve operation");
  }

  return post as PostInfo;
}

/**
 * Publish a post immediately
 * @param postId - Post/Output ID
 * @param token - Optional auth token
 */
export async function publishPost(postId: string, token?: string): Promise<PostInfo> {
  const response = await apiClient.post(
    `/api/posts/${encodeURIComponent(postId)}/publish`,
    postMutationResponseSchema,
    {},
    withAuth(token)
  );

  const post = response.data.post || response.data.output;
  if (!post) {
    throw new Error("Post not returned from publish operation");
  }

  return post as PostInfo;
}

/**
 * Schedule a post for future publication
 * @param postId - Post/Output ID
 * @param scheduledFor - Date/time to publish
 * @param token - Optional auth token
 */
export async function schedulePost(
  postId: string,
  scheduledFor: Date,
  token?: string
): Promise<PostInfo> {
  const response = await apiClient.post(
    `/api/posts/${encodeURIComponent(postId)}/schedule`,
    schedulePostResponseSchema,
    { scheduledFor: scheduledFor.toISOString() },
    withAuth(token)
  );

  const post = response.data.post || response.data.output;
  if (!post) {
    throw new Error("Post not returned from schedule operation");
  }

  return {
    ...post,
    scheduledFor: response.data.scheduledFor,
  } as PostInfo;
}

/**
 * Delete a post
 * @param postId - Post/Output ID
 * @param token - Optional auth token
 */
export async function deletePost(postId: string, token?: string): Promise<void> {
  await apiClient.delete(
    `/api/posts/${encodeURIComponent(postId)}`,
    postMutationResponseSchema,
    withAuth(token)
  );
}

/**
 * Update a post's content
 * @param postId - Post/Output ID
 * @param updates - Fields to update
 * @param token - Optional auth token
 */
export async function updatePost(
  postId: string,
  updates: {
    text?: string;
    title?: string;
    platform?: string;
    meta?: Record<string, unknown>;
  },
  token?: string
): Promise<PostInfo> {
  const response = await apiClient.patch(
    `/api/posts/${encodeURIComponent(postId)}`,
    postMutationResponseSchema,
    updates,
    withAuth(token)
  );

  const post = response.data.post || response.data.output;
  if (!post) {
    throw new Error("Post not returned from update operation");
  }

  return post as PostInfo;
}

/**
 * Session API methods for FluxBoard
 *
 * All API calls support optional authentication via accessToken parameter.
 * When provided, the Authorization header will be included in requests.
 *
 * Enhanced with comprehensive Zod schema validation for runtime type safety.
 */

import { z } from "zod";
import { apiClient, type RequestOptions } from "./client";
import type { SessionConfig } from "@livestream-copilot/shared";
import {
  getSessionsResponseSchema,
  getSessionByIdResponseSchema,
  startSessionResponseSchema,
  endSessionResponseSchema,
  forceStopSessionResponseSchema,
  sessionStatusResponseSchema,
  getSessionOutputsResponseSchema,
  updateSessionResponseSchema,
  apiResponseSchema,
  sessionOutputSchema,
  type SessionListItem,
  type PaginationInfo,
} from "./schemas";

/**
 * Create request options with optional auth header
 */
function withAuth(accessToken?: string, options: RequestOptions = {}): RequestOptions {
  if (!accessToken) return options;

  return {
    ...options,
    headers: {
      ...options.headers,
      Authorization: `Bearer ${accessToken}`,
    },
  };
}

/**
 * Full session details with events (for compatibility)
 */
export interface SessionDetails {
  sessionId: string;
  workflow: SessionConfig["workflow"];
  captureMode: SessionConfig["captureMode"];
  title?: string;
  startedAt: number;
  endedAt?: number;
  clipCount: number;
  outputCount: number;
  participants: SessionConfig["participants"];
  events?: Array<{
    id: string;
    type: string;
    ts: number;
    payload: unknown;
  }>;
}

/**
 * Configuration for starting a new session
 */
export interface StartSessionConfig {
  workflow: SessionConfig["workflow"];
  captureMode: SessionConfig["captureMode"];
  title?: string;
  participants?: Array<{ id: string; name: string }>;
}

/**
 * Response from starting a session
 */
export interface StartSessionResponse {
  sessionId: string;
  startedAt: number;
}

/**
 * Response from ending a session
 */
export interface EndSessionResponse {
  sessionId: string;
  endedAt: number;
  duration: number;
  clipCount: number;
  outputCount: number;
}

/**
 * Session output item
 */
export interface SessionOutput {
  id: string;
  sessionId: string;
  type: string;
  label: string | null;
  content: string;
  metadata: Record<string, unknown> | null;
  createdAt: string;
}

/**
 * Get all sessions from the backend API
 * @param limit - Maximum number of sessions to return (default: 50)
 * @param offset - Number of sessions to skip (default: 0)
 * @param accessToken - Optional access token for authentication
 * @param filters - Optional filters for workflow and active status
 */
export async function getSessions(
  limit = 50,
  offset = 0,
  accessToken?: string,
  filters?: { workflow?: string; active?: boolean }
): Promise<{ sessions: SessionListItem[]; pagination: PaginationInfo }> {
  const params: Record<string, string | number | boolean | undefined> = { limit, offset };
  if (filters?.workflow) {
    params.workflow = filters.workflow;
  }
  if (filters?.active !== undefined) {
    params.active = filters.active;
  }

  const response = await apiClient.get(
    "/api/sessions",
    getSessionsResponseSchema,
    withAuth(accessToken, { params })
  );

  if (!response.success) {
    throw new Error("Failed to fetch sessions");
  }

  return response.data;
}

/**
 * Get a single session by ID from the backend API
 * @param id - Session ID
 * @param accessToken - Optional access token for authentication
 */
export async function getSessionById(
  id: string,
  accessToken?: string
): Promise<SessionListItem> {
  const response = await apiClient.get(
    `/api/sessions/${encodeURIComponent(id)}`,
    getSessionByIdResponseSchema,
    withAuth(accessToken)
  );

  if (!response.success) {
    throw new Error(`Failed to fetch session ${id}`);
  }

  return response.data.session;
}

/**
 * @deprecated Use getSessions instead
 * List all sessions (legacy function for compatibility)
 */
export async function listSessions(
  limit = 50,
  offset = 0
): Promise<SessionListItem[]> {
  const { sessions } = await getSessions(limit, offset);
  return sessions;
}

/**
 * @deprecated Use getSessionById instead
 * Get a single session by ID (legacy function for compatibility)
 */
export async function getSession(
  id: string,
  _includeEvents = false
): Promise<SessionDetails> {
  const session = await getSessionById(id);

  // Map new API format to legacy SessionDetails format
  return {
    sessionId: session.id,
    workflow: session.workflow as SessionConfig["workflow"],
    captureMode: session.captureMode as SessionConfig["captureMode"],
    title: session.title || undefined,
    startedAt: new Date(session.startedAt).getTime(),
    endedAt: session.endedAt ? new Date(session.endedAt).getTime() : undefined,
    clipCount: session.counts.clips,
    outputCount: session.counts.outputs,
    participants: session.participants.map((name, index) => ({
      id: `participant-${index}`,
      name,
    })),
  };
}

/**
 * Start a new session
 * @param config - Session configuration
 * @param accessToken - Optional access token for authentication
 */
export async function startSession(
  config: StartSessionConfig,
  accessToken?: string
): Promise<StartSessionResponse> {
  // Map frontend config to backend format
  const backendConfig = {
    workflow: config.workflow,
    captureMode: config.captureMode,
    title: config.title || "Untitled Session",
    participants: config.participants || [],
  };

  return apiClient.post(
    "/session/start",
    startSessionResponseSchema,
    backendConfig,
    withAuth(accessToken)
  );
}

/**
 * End a session by ID
 * Calls POST /api/sessions/:id/end to mark the session as ended in the database.
 * @param id - Session ID to end
 * @param accessToken - Optional access token for authentication
 */
export async function endSession(
  id: string,
  accessToken?: string
): Promise<EndSessionResponse> {
  const response = await apiClient.post(
    `/api/sessions/${encodeURIComponent(id)}/end`,
    endSessionResponseSchema,
    {},
    withAuth(accessToken)
  );

  if (!response.success) {
    throw new Error("Failed to end session");
  }

  const { session, duration } = response.data;

  return {
    sessionId: session.id,
    endedAt: session.endedAt ? new Date(session.endedAt).getTime() : Date.now(),
    duration: duration || 0,
    clipCount: session.counts?.clips || 0,
    outputCount: session.counts?.outputs || 0,
  };
}

/**
 * Force-stop the active session in memory
 * @param accessToken - Optional access token for authentication
 */
export async function forceStopSession(
  accessToken?: string
): Promise<{ ok: boolean; message: string }> {
  return apiClient.post(
    "/session/force-stop",
    forceStopSessionResponseSchema,
    {},
    withAuth(accessToken)
  );
}

/**
 * Get the currently active session, if any
 * @param accessToken - Optional access token for authentication
 */
export async function getActiveSession(
  accessToken?: string
): Promise<SessionDetails | null> {
  try {
    const response = await apiClient.get(
      "/session/status",
      sessionStatusResponseSchema,
      withAuth(accessToken)
    );

    if (!response.ok || !response.active || !response.sessionId) {
      return null;
    }

    // Use the new top-level fields from the backend response
    // Fall back to legacy nested fields if needed
    const workflow = response.workflow || response.session?.workflow || "streamer";
    const captureMode = response.captureMode || response.session?.captureMode || "av";
    const title = response.title || response.session?.title || "Active Session";
    const startedAt = response.startedAt || response.t0 || Date.now();
    const participants = response.participants || response.session?.participants || [];

    return {
      sessionId: response.sessionId,
      workflow: workflow as SessionConfig["workflow"],
      captureMode: captureMode as SessionConfig["captureMode"],
      title,
      startedAt,
      clipCount: 0,
      outputCount: 0,
      participants: participants.map((p, index) =>
        typeof p === "string"
          ? { id: `participant-${index}`, name: p }
          : p
      ),
    };
  } catch (error) {
    // Network error or server down
    return null;
  }
}

/**
 * Get outputs for a specific session
 * @param id - Session ID
 * @param accessToken - Optional access token for authentication
 */
export async function getSessionOutputs(
  id: string,
  accessToken?: string
): Promise<SessionOutput[]> {
  const response = await apiClient.get(
    `/api/sessions/${encodeURIComponent(id)}/outputs`,
    getSessionOutputsResponseSchema,
    withAuth(accessToken)
  );

  if (!response.success) {
    throw new Error(`Failed to fetch outputs for session ${id}`);
  }

  return response.data.outputs;
}

/**
 * Update session metadata
 * @param id - Session ID
 * @param updates - Partial session updates (title, participants)
 * @param accessToken - Optional access token for authentication
 */
export async function updateSession(
  id: string,
  updates: { title?: string; participants?: string[] },
  accessToken?: string
): Promise<SessionListItem> {
  const response = await apiClient.patch(
    `/api/sessions/${encodeURIComponent(id)}`,
    updateSessionResponseSchema,
    updates,
    withAuth(accessToken)
  );

  if (!response.success) {
    throw new Error(`Failed to update session ${id}`);
  }

  return response.data.session;
}

/**
 * Delete a session
 * @param id - Session ID
 * @param accessToken - Optional access token for authentication
 */
export async function deleteSession(
  id: string,
  accessToken?: string
): Promise<void> {
  const deleteResponseSchema = apiResponseSchema(z.object({ message: z.string() }));

  const response = await apiClient.delete(
    `/api/sessions/${encodeURIComponent(id)}`,
    deleteResponseSchema,
    withAuth(accessToken)
  );

  if (!response.success) {
    throw new Error(`Failed to delete session ${id}`);
  }
}

